            'fields_hint' => 'Eit felt som er slått av for saka sitt selskap, eller eit Team-felt på ein installasjon utan team, vert hoppa over for den saka - ingen vert bedt om å fylle ut noko dei ikkje kan sjå. Å slå saman saker utløyser aldri dette.',
