        'intros' => [
            'custom_fields' => 'Lag dei ekstra opplysningane ein type sak treng - til dømes ein startdato og eit brukarnamn på ein ny tilsett - og vel kva for sakstypar kvar av dei er på. Kvart felt avgjer sjølv om det må fyllast ut når ei sak blir registrert, når ho blir lukka, eller begge delar, og om bestillaren blir spurd om det i portalen.',
            'checklists' => 'Ei sjekkliste kan merkje steg som obligatoriske. Dette avgjer kva som skjer om nokon lukkar ei sak før desse stega er kryssa av.',
            'mandatory_fields' => 'Vel kva for saksfelt som må fyllast ut før ei sak vert lukka, og kva som skjer når nokon lukkar ei med nokon av dei tomme. Regelen gjeld overalt ei sak kan lukkast: sakskjermen, massehandlingar, REST API-et og arbeidsflytar.',
            'departments' => 'Avdelingar grupperer og rutar saker til rett del av organisasjonen — opprett dei servicedesken din brukar til å kategorisere og fordele arbeid.',
            'teams' => 'Team avgjer kva for avdelingar analytikarar har tilgang til. Tildel avdelingar til team, og tildel så analytikarar til team for å styre tilgangen deira.',
            'ticket_types' => 'Sakstypar klassifiserer kva ein førespurnad er (til dømes hending eller tenesteførespurnad) — definer typane analytikarar kan setje på ei sak.',
            'ticket_origins' => 'Sakskjelder registrerer korleis ei sak kom inn (til dømes e-post, telefon eller portal) — definer kjeldene analytikarar kan velje mellom.',
            'mailboxes' => 'Postkasser koplar FreeITSM til e-postkontoar slik at innkomande meldingar blir saker og svar går ut att — legg til og autentiser dei servicedesken din overvakar.',
            'privacy' => 'Ei sak inneheld ikkje berre samtalen din med den som melde henne inn. Vidaresender du til ein leverandør, eller set ein kollega på kopi, hamnar den meldinga på den same saka — og svaret deira landar der òg. Dette avgjer kor mykje av det innmeldaren ser i sjølvbeteningsportalen.',
            'indexing' => 'Teksten inni vedlegg vert lesen slik at han kan søkjast i. Word-, Excel-, PowerPoint- og reintekstfiler vert lesne av FreeITSM sjølv, i det augeblikket dei kjem inn. PDF-ar, eldre Office-filer og skanna dokument treng ei eiga teneste for dokumentlesing — sett det opp under <strong>System &rarr; Integrasjonar &rarr; Apache Tika</strong> — og fordi desse tek mykje lengre tid, vert dei lesne i bakgrunnen. Desse to brytarane avgjer når det bakgrunnsarbeidet skjer.',
            'merge_behaviour' => 'Når to saker viser seg å vere det same, kan ein analytikar slå dei saman. Desse innstillingane avgjer kva det gjer med saksreferansane innmeldarane dine sit med, og kva som skjer med samtalane. Dei gjeld for alle — ei samanslåing endrar kva kunden ser, så to analytikarar på same postkasse må ikkje kunne vere ueinige om det.',
            'reply_templates' => 'Standardsvar analytikarane dine kan setje inn i eit svar i staden for å skrive dei på nytt. Dette er dei delte som heile teamet ser — dei private malane til ein analytikar blir lagra frå svarvindauget og står ikkje oppførte her.',
            'rota_shifts' => 'Skift er malane for arbeidsmønster (til dømes Tidleg, Sein, Beredskap) som analytikarar blir sette opp på i bemanningsplanen — definer dei her før du byggjer vaktlista.',
            'analysts' => 'Analytikarar er dei tilsette som loggar inn og jobbar med saker — legg dei til, tilbakestill passord og tildel dei til team for å styre tilgangen deira.',
            'general' => 'Generelle innstillingar styrer korleis saker oppfører seg - gjenopning, utsetjing og kor lenge meldingar og trådar blir viste.',
            'statuses' => 'Tilstandane i arbeidsflyten ei sak kan vere i. Statusar merkte som <em>Lukka</em> tel som avsluttande — dei blir brukte av rapportar, teljarane i Watchtower og det automatiske tidsstempelet for lukking ved tildeling. Nøyaktig éin status er standard for nye saker.',
            'priorities' => 'Prioritetsnivåa som blir viste på saker. Nøyaktig éin prioritet er standard for nye saker.',
            'rota_locations' => 'Kvar kvar analytikar jobbar ein gjeven dag — blir brukt av bemanningsplanen og vist som eit farga merke på kvar oppføring. Nøyaktig éin stad er standard for nye vaktlisteoppføringar.',
            'email_templates' => 'Automatiske e-postsvar som blir utløyste av hendingar på saker. Berre den første aktive malen per hending blir brukt.',
        ],
        'messaging' => [
            'channels_heading' => 'Meldingskanalar',
            'channels_intro' => 'Lat kundar prate med ein analytikar over WhatsApp — kvar melding blir ei sak, akkurat som e-post. Legg til ein kanal nedanfor, og lim så <strong>webhook-URL-en</strong> til han inn hos leverandøren din (Twilio eller Meta) slik at innkomande meldingar når fram til denne installasjonen.',
            'base_url_label' => '<strong>Offentleg grunn-URL</strong>',
            'base_url_placeholder' => 'https://ditt-domene.no  (eller ngrok-adressa di medan du testar)',
            'base_url_help' => 'Adressa leverandørar brukar for å nå denne installasjonen. Set du henne, blir webhook-URL-ane nedanfor klare til å kopierast rett inn. Lat henne stå tom for å bruke den adressa du surfar frå. Testar du lokalt? Køyr <code>ngrok http 80</code> og lim inn <code>https://…ngrok-free.dev</code>-adressa han skriv ut.',
            'templates_heading' => 'Meldingsmalar',
            'templates_intro' => 'Førehandsgodkjende malar lèt ein analytikar svare <strong>etter at 24-timarsvindauget er lukka</strong>. WhatsApp tillèt berre fritekst innan 24 timar etter den siste meldinga til kunden; utanfor det kan berre ein mal Meta/Twilio har godkjent, sendast. Opprett og få malen godkjend hos leverandøren din, og legg så inn definisjonen her (med plasshaldarane <code>{{1}}</code> og <code>{{2}}</code>) slik at analytikarar kan velje og fylle han ut.',
