        'sla' => [
            'heading' => 'Tenestenivåavtalar',
            'intro' => 'SLA-ar som tek omsyn til arbeidstid, med mål for responstid og løysingstid per prioritet. Klokka stoppar på statusar merkte «Set SLA på pause» under <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">Statusar-fana</a>. Sjå <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">designnotata</a>.',
