            'enforce_from' => 'Handhev SLA-ar frå',
            'enforce_from_help' => 'Lat feltet stå tomt for å <strong>slå av SLA-handhevinga heilt</strong>. Set du eit tidspunkt, er det berre saker som er oppretta på eller etter det tidspunktet som blir vurderte &mdash; nyttig for å la eksisterande saker gå fri når du slår på SLA-ar for første gong.',
