            'targets_heading' => 'SLA-mål per prioritet',
            'targets_intro' => 'Responstid og løysingstid for kvar sakprioritet. Tidene er i minutt (60 = 1 time, 240 = 4 timar, 1440 = 1 døgn). Kalenderen avgjer kva for arbeidstid klokka går mot. Lat feltet stå tomt for å hoppe over det målet.',
            'col_priority' => 'Prioritet',
            'col_response_mins' => 'Respons (min)',
            'col_resolution_mins' => 'Løysing (min)',
            'col_calendar' => 'Kalender',
            'col_save' => 'Lagre',
            'calendars_heading' => 'Arbeidskalendrar',
            'calendars_intro' => 'Definer arbeidstid, tidssoner og lister over heilagdagar. Kalendrar blir brukte av SLA-måla (ovanfor) og av einskildprioritetar. Éin kalender er standard for nye prioritetar.',
            'col_name' => 'Namn',
            'col_timezone' => 'Tidssone',
            'col_hours' => 'Timar',
            'col_holidays' => 'Heilagdagar',
            'col_default' => 'Standard',
            'default_badge' => 'Standard',
            'no_active_priorities' => 'Ingen aktive prioritetar - legg til nokre på fana Prioritetar.',
            'no_calendars' => 'Ingen kalendrar definerte enno. Legg til ein ovanfor.',
            'col_actions' => 'Handlingar',
            'notifs_heading' => 'Varsel ved brot',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Slik verkar varslingsreglane</strong>Kvar regel har fire delar: eit <strong>omfang</strong>, ein <strong>utløysar</strong>, eit <strong>mål</strong> og ei liste over <strong>mottakarar</strong>.<br><br><strong>Omfang</strong> er anten <em>Standard</em> (regelen gjeld saker i alle avdelingar) eller ei <em>bestemt avdeling</em> (regelen gjeld berre saker i den avdelinga).<br>Når ei sak blir vurdert, ser systemet først etter ein regel som passar avdelinga hennar &mdash; finst han, vinn den regelen, og standarden blir ignorert. Finst det ingen avdelingsspesifikk regel, blir standardregelen brukt. Slik kan du setje fornuftige standardar som dekkjer alle avdelingar, og så skjere ut unntak der eitt team har andre behov for eskalering.<br><br><strong>Utløysar</strong> er anten <em>Åtvaring</em> (saka har passert åtvaringsterskelen &mdash; eit mogleg brot nærmar seg) eller <em>Brot</em> (saka har no overskride SLA-målet sitt &mdash; eit faktisk brot). Kvar av dei er sin eigen regel, så du kan varsle ulike personar ved åtvaringar og ved brot.<br><br><strong>Mål</strong> er kva for ei SLA-klokke som skal følgjast &mdash; <em>Respons</em>, <em>Løysing</em> eller <em>Begge</em>.<br><br><strong>Mottakarar</strong> kan vere ein kva som helst kombinasjon av: den saka er tildelt akkurat no, alle analytikarar i teama til saksavdelinga, éin namngjeven analytikar og/eller ei liste med frie e-postadresser (nyttig for delte innboksar eller e-postbruer til Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Ingen reglar = ingen e-postar.</strong> Sjølv om ei sak bryt SLA-en, skjer det ingenting før du legg til minst éin regel (start med eit par på standardomfang, eitt for åtvaring og eitt for brot, så har du dekning for alt).',
            'notifs_dedup' => 'Kvar sak utløyser høgst éin e-post per mål per utløysar &mdash; cron-jobben held styr på kva som alt er sendt, så du slepp duplikat.',
            'col_scope' => 'Omfang',
            'col_trigger' => 'Utløysar',
            'col_target' => 'Mål',
            'col_recipients' => 'Mottakarar',
            'col_active' => 'Aktiv',
            'notifs_cron_note' => 'Cron-jobben som sender desse e-postane, ligg i <code>cron/sla_breach_check.php</code>. Sjå <code>docs/sla-cron-setup.md</code> for oppsett med Oppgåveplanlegging i Windows og cron i Linux.',
            'cron_heading' => 'Cron-aktivitet',
