            'cron_intro' => 'Dei siste <span id="slaCronRunsLimit">20</span> køyringane av cron-jobben for brotsjekk (CLI og HTTP). Inkluderer avviste førespurnader (mengdeavgrensa, mislukka autentisering) slik at den same fasiten dekkjer både mengdeavgrensinga og tryggingsrevisjonar. Blir rydda automatisk etter <strong><span id="slaCronRetentionDays">30</span> dagar</strong>; minste intervall mellom vellukka køyringar er <strong><span id="slaCronMinInterval">30</span> s</strong> (begge kan endrast i <code>system_settings</code>).',
            'col_when' => 'Når',
