        'numbering' => [
            'heading' => 'Saksnummerering',
            'intro' => 'Kvar sak får ein referanse. Det er det folk les opp i telefonen, skriv på eit skjema og søkjer etter seks månader seinare, så det er verdt at det er noko ein person kan seie. Du vel forma her.',
            'style' => 'Korleis nummer vert laga',
