            'style_sequential_help' => 'TICKET-000001, TICKET-000002, og så vidare. Lett å seie, lett å kjenne att, og rekkjefølgja fortel deg kva som kom først.',
            'style_random' => 'Tilfeldig',
            'style_random_help' => 'Tre bokstavar og åtte siffer, som CKQ-418-73926. Dette er det FreeITSM alltid har gjort. Ingen kan gjette kor mange saker du har, men ingen kan lese ein opp heller.',
            'format' => 'Korleis eit nummer ser ut',
            'format_help' => 'Set <code>{######}</code> der siffera skal vere &mdash; ein firkanttast per siffer. Alt anna vert halde slik du skriv det. Du kan òg bruke <code>{YYYY}</code> eller <code>{YY}</code> for året, <code>{MM}</code> og <code>{DD}</code>, og <code>{TYPE}</code> eller <code>{COMPANY}</code> for ein kort kode henta frå sakstypen eller selskapet. Til dømes <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'Dei neste ville sjå slik ut',
            'start' => 'Start teljinga frå',
            'start_help' => 'Nyttig viss du flyttar frå eit anna system og vil halde fram der det slutta.',
            'scope' => 'Tel separat for',
            'scope_global' => 'Éin sekvens for alt',
            'scope_per_type' => 'Kvar sakstype',
            'scope_per_company' => 'Kvart selskap',
            'scope_help' => 'Å telje per sakstype gir hendingar og førespurnadar sine eigne nummerseriar, som er slik dei fleste store brukarstøtte-team gjer det. Viss du tel separat, må formatet seie kva som er kva — set {TYPE} eller {COMPANY} inn i det, elles ville kvar gruppe produsere dei same numra.',
            'reset' => 'Start på nytt',
            'reset_never' => 'Aldri — hald fram med å telje',
            'reset_yearly' => 'Kvart år',
            'reset_monthly' => 'Kvar månad',
            'reset_help' => 'Berre nyttig viss året eller månaden er ein del av nummeret, elles får du duplikat. Kombiner med noko som <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Ingenting som alt er nummerert, endrar seg.</strong> Eksisterande saker held på referansen dei har, og kvar referanse FreeITSM nokosinne har gitt ut, held fram med å fungere &mdash; òg i svar på gamle e-postar. Viss du vil ha eksisterande saker nummererte på nytt òg, er det eit verktøy for det under. <strong>Du går ikkje tom for siffer:</strong> breidda du vel, er eit minimum, så sak 1 000 001 vert berre eitt siffer lengre i staden for å bryte saman.',
            'saved' => 'Saksnummereringa er lagra.',
            'renumber_heading' => 'Nummerer eksisterande saker på nytt',
            'renumber_intro' => 'Skriv referansen på kvar eksisterande sak om til skjemaet over, eldste først. Mest nyttig rett etter ein flytting frå eit anna system, når du vil at alt skal sjå konsekvent ut.',
            'renumber_safety' => '<strong>Gamle referansar held fram med å fungere.</strong> Kvart nummer ei sak nokosinne har hatt, vert hugsa, så eit svar på ein e-post som siterer det gamle, hamnar framleis på rett sak &mdash; akkurat som når saker vert slått saman. Eit pensjonert nummer vert heller aldri gitt til ei anna sak. Dette er derimot ikkje noko du kan angre, så sjå på førehandsvisinga først.',
            'renumber_preview' => 'Førehandsvising',
            'renumber_go' => 'Nummerer på nytt',
            'renumber_preview_first' => 'Sjå førehandsvisinga først — knappen vert aktivert når du har sett kva han ville gjort.',
            'renumber_preview_heading' => 'Berre førehandsvising &mdash; ingenting er endra.',
            'renumber_done_heading' => 'Sakene er nummererte på nytt.',
            'renumber_summary' => '{changing} av {total} sak(er) ville blitt nummererte på nytt. {skipped} stemmer alt.',
            'renumber_next_after' => 'Den neste nye saka ville vore {number}.',
            'renumber_confirm_title' => 'Nummerer alle saker på nytt?',
            'renumber_confirm' => 'Dette skriv referansen på kvar eksisterande sak om.

Gamle referansar held fram med å fungere, så svar på gamle e-postar finn framleis rett sak. Men numra folk har skrive ned, sett på skjema og lagra i sine eigne rekneark, vil ikkje lenger vere dei som vert viste i FreeITSM.

Dette kan ikkje angrast. Halde fram?',
