        'general' => [
            'system_name' => 'Systemnamn',
            'system_name_moved' => 'Systemnamnet - første del av kvar sidetittel - blir sett i {link}, fordi det gjeld for kvar modul.',
            'system_name_moved_link' => 'System -> Merkevare',
            'system_name_placeholder' => 't.d. Servicedesk saksbehandlingssystem',
            'system_name_help' => 'Vist i starten av kvar sidetittel - namnet i nettlesarfana og i bokmerke. Tomt betyr «Service Desk».',
            'reopen_label' => 'Opning att',
            'reopen_toggle' => 'Opne ei lukka sak att når innmeldaren svarar',
            'snooze_hour_label' => 'Starten på arbeidsdagen',
            'snooze_hour_help' => 'Tidspunktet ei sak som er sett på vent til «I morgon» eller «Neste veke», kjem tilbake. Blir lese i kvar analytikar si eiga tidssone, så ein servicedesk spreidd over fleire soner får kvar sin morgon.',
            'collapse_heading' => 'Lange meldingar',
            'collapse_desc' => 'Lange e-postar gøymer det du opna saka for å lese. Meldingar høgare enn grensa under vert forkorta med ei Vis meir-lenke. Ingenting vert sletta — heile meldinga er alltid eitt trykk unna.',
            'collapse_enabled_label' => 'Forkort lange meldingar',
            'collapse_lines_label' => 'Forkort meldingar høgare enn omtrent',
            'collapse_lines_help' => 'linjer. Ei melding berre litt over grensa vert late vere, så lenka aldri dukkar opp for berre to ord si skuld.',
            'collapse_newest_label' => 'Vis alltid den nyaste meldinga i sin heilskap',
            'collapse_newest_help' => 'Meldinga du kom for å lese, vert aldri forkorta.',
            'collapse_quoted_label' => 'Forkort sitert historikk',
            'collapse_quoted_help' => 'Eit kort svar med ei lang sitert kjede under er kort etter kvar linjeteljing og likevel uleseleg, så sitert historikk vert forkorta separat.',
            'collapse_remember_label' => 'Hugs kva eg opna',
            'collapse_remember_help' => 'Meldingar du utvidar, held seg utvida på denne eininga, så å arbeide gjennom ein tråd angrar seg ikkje sjølv ved kvar oppdatering.',
            'group_older_label' => 'Fald bort eldre meldingar',
            'group_older_help' => 'Utover talet under, faldar eldre meldingar seg saman til éi linje du kan opne. Ei lang sak er eit anna problem enn ei lang melding.',
            'group_show_label' => 'Hald dette talet nylege meldingar opne',
            'flag_duplicates_label' => 'Peik ut meldingar som har kome før',
            'flag_duplicates_help' => 'Ei ny-sending, ei duplikatlevering eller ein retur som ber originalen tilbake, vert falda bort med eit notat som seier kva melding han matchar. Ingenting vert sletta.',
            'team_folders_heading' => 'Teammapper',
            'team_folders_label' => 'Analytikarar ser',
            'team_folders_all' => 'Alle team',
            'team_folders_mine' => 'Berre teama dei høyrer til',
            'team_folders_help' => 'Endrar berre mappelista - ingen mistar oversikta over ei sak. Eit team med saker ein analytikar kan sjå, blir framleis vist, så mappene held fram med å gå opp. Administratorar ser alltid alle team.',
            'watch_heading' => 'Overvaking av saker',
            'watch_help' => 'Kva overvakarane av ei sak får vite om. Dei personlege varselinnstillingane til kvar overvakar gjeld framleis oppå dette.',
            'watch_inactive_label' => 'Når ein overvakar blir deaktivert',
            'watch_inactive_stop' => 'Slutt å varsle dei - behald overvakinga deira i tilfelle dei kjem tilbake',
            'watch_inactive_remove' => 'Fjern dei frå alle saker dei overvakar',
            'watch_inactive_help' => 'Ein deaktivert analytikar får aldri varsel. Slutt held overvakinga skjult og set henne tilbake om analytikaren blir aktivert att; Fjern slettar henne når analytikaren blir deaktivert. Fjerning gjeld frå det tidspunktet dette blir lagra.',
            'watch_event_ticket_reply_received' => 'Bestillaren svarar',
            'watch_event_ticket_note_added' => 'Eit notat blir lagt til',
            'watch_event_ticket_status_changed' => 'Statusen endrar seg',
            'watch_event_ticket_priority_changed' => 'Prioriteten endrar seg',
            'watch_event_ticket_assigned' => 'Saka blir tildelt på nytt',
            'watch_event_sla_warning' => 'Ho nærmar seg SLA-målet',
            'watch_event_sla_breached' => 'Ho bryt SLA-målet',
            'ai_heading' => 'AI reading aids',
            'ai_desc' => 'Optional, and off until you turn them on: unlike everything else on this page these use your own AI provider and cost money per use. The provider, model and API key are configured once on the Reply cleanup tab. Nothing an AI writes ever replaces the ticket — the conversation stays exactly where it is, in full.',
            'ai_summary_label' => 'Keep a short AI summary at the top of each ticket',
            'ai_summary_help' => 'A few lines saying where the ticket stands, written on request and kept up to date. It always shows when it was written, how much it read, and how far the conversation has moved on since. Every version is kept, so a worse summary never destroys a better one.',
            'ai_auto_label' => 'Refresh it automatically after this many new messages',
            'ai_auto_help' => '0 means never — the Refresh button is then the only way, and nothing is ever charged without somebody asking. A refresh only happens when an analyst opens the ticket, so a busy queue nobody is reading costs nothing.',
            'ai_max_label' => 'Messages to read',
            'ai_max_help' => 'How far back a summary reads. A longer ticket is read from its most recent end, and the summary says so rather than describing a beginning it never saw.',
            'ai_notes_label' => 'Let it read internal notes',
            'ai_notes_help' => 'Internal notes often hold what was actually tried. They are staff-only either way — the summary is never shown to a requester — but turn this off if notes on your desk hold things that should not leave it.',
            'ai_read_label' => 'Tilby «Les han» på ei sak',
            'ai_confidential_label' => 'Konfidensielle saker og KI',
            'ai_confidential_block' => 'Send dei aldri til KI (tilrådd)',
            'ai_confidential_allow' => 'Behandle dei som alle andre saker',
            'ai_confidential_help' => 'Gjeld kvar KI-funksjon som les ei sak: samandraget, Les han, opprydding av svar, Spør KI, samandrag ved samanslåing, kunnskapsartiklar, kanalsamandrag, problemanalyse og war room-boten. Ei konfidensiell sak blir anten ikkje send, eller - der mange saker blir lesne samtidig - utelaten eller berre vist med nummer.',
            'ai_read_help' => 'A button that reads the whole ticket and briefs you on it: what happened, what is unresolved, and what it would do next. Asked for and read once, stored nowhere.',
            'reopen_help' => 'Gjeld uansett kvar ein innmeldar kjem tilbake — sjølvbeteningsportalen, eit svar på varslings-e-posten din, WhatsApp eller nettprat. Saka går tilbake til den første opne statusen din. Berre saker med ein status som er merkt som lukka, blir råka (set kva for nokre det er under Statusar).',
            'location_label' => 'Stad for ei ny sak',
            'location_toggle' => 'Bruk staden til bestillaren',
            'location_help' => 'Ei ny sak startar med staden til bestillaren (frå posten hans), uansett veg inn - e-post, portalen, chat, API-et. Analytikarar kan endre han på saka. Seinare flyttingar av bestillaren endrar ikkje gamle saker.',
