        'privacy' => [
            'third_party_label' => 'Meldingar som blir sende til andre enn innmeldaren',
            'opt_hide' => 'Skjul dei for innmeldaren',
            'opt_hide_help' => 'Meldinga og vedlegga hennar blir ikkje viste i portalen til innmeldaren i det heile. Tilrådd: dei fleste går ut frå at det å vidaresende ei sak til ein leverandør er noko privat.',
            'opt_no_attachments' => 'Vis meldinga, men ikkje vedlegga',
            'opt_no_attachments_help' => 'Innmeldaren ser at de kontakta nokon andre og kva som vart skrive, men kan ikkje laste ned vedlagde filer.',
            'opt_show' => 'Vis alt',
            'opt_show_help' => 'Innmeldaren ser heile saka nøyaktig slik analytikarane gjer, medrekna vidaresendingar og svar frå tredjepartar. Dette var åtferda før denne innstillinga fanst.',
            'always_visible_note' => '<strong>Alltid synleg for innmeldaren:</strong> deira eigne meldingar, og alle svar som er adresserte til dei. <strong>Aldri synleg:</strong> interne notat — dei er skjulte i portalen uansett kva denne innstillinga står på. Meldingar på WhatsApp og nettprat blir alltid viste, fordi dei samtalane per definisjon er mellom innmeldaren og servicedesken deira.',
            'timezone' => 'Tidssone',
