        'reply_cleanup' => [
            'intro1' => 'Når ein analytikar skriv eit grovt svar i skrivevindauget på saka, skriv knappen <strong>✨ Rydd opp</strong> det om til ein ordentleg formatert e-post — han legg til ei «Hei [namn],»-helsing, rettar grammatikken, brukar tonen du vel nedanfor, og avsluttar med «Med venleg helsing,». Han vil <strong>ikkje</strong> finne på tekniske detaljar eller fylle på med tomt innhald.',
            'intro2' => 'Denne funksjonen brukar sin eigen Anthropic API-nøkkel (åtskild frå RFP-KI og kunnskaps-KI), slik at bruken blir vist som ei eiga linje i faktureringsoversikta hos Anthropic.',
            'tone' => 'Tone',
