            'custom_placeholder' => 't.d. Avslutt alltid med \'Tusen takk,\'&#10;Omtal firmaet som \'BillCorp\'&#10;Bruk konsekvent nynorsk',
            'custom_help' => 'Blir lagt til systeminstruksjonen som blir vist til høgre. Bruk dette til tilpassingar for organisasjonen din (variantar av avslutningshelsing, firmanamn, språkpreferansar). Dei harde tryggingsreglane og utdataformatet går framleis føre.',
            'prompt_summary' => 'Vis systeminstruksjonen (skriveverna)',
