        'csat_tab' => [
            'intro1' => 'Når ei sak blir lukka, blir innmeldaren send ei kort undersøking på e-post der dei blir bedne om å vurdere opplevinga frå 1 til 5. Svara blir registrerte på analytikaren som lukka saka, slik at du kan hente ut KTI-trendar per analytikar, og dei blir viste som eit element på oversiktssida.',
            'intro2' => 'E-posten med undersøkinga blir sett opp under <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">E-postmalar</a> &mdash; opprett ein mal med hendinga <strong>KTI-undersøking</strong>, og legg <code>[csat_link]</code> inn i brødteksten for å setje inn eingongslenkja til vurderinga.',
            'mode_off' => 'Av',
            'mode_off_help' => 'Det blir ikkje sendt e-postar med undersøkingar.',
            'mode_auto' => 'Automatisk ved lukking',
            'mode_auto_help' => 'Ei undersøking blir send automatisk når ei sak går over i ein lukka status.',
            'mode_manual' => 'Berre manuelt',
            'mode_manual_help' => 'Analytikarar klikkar <em>Tilbakemelding</em> i verktøylinja på saka når dei vil spørje.',
            'delay_help' => 'Vent så mange minutt etter lukking før sending. <code>0</code> = med det same. Nyttig dersom du vil at brukaren skal få stadfesta at løysinga faktisk heldt, før dei blir bedne om å vurdere henne.',
            'reminder' => 'Send éi påminning om undersøkinga ikkje er svara på',
            'reminder_hours' => 'Påminn etter (timar)',
            'reminder_help' => 'Éi påminning på det meste, per e-post, med same lenke - så begge e-postane fungerer og berre éi vurdering blir behalden. Berre undersøkingar sende per e-post blir følgde opp med påminning, anten dei gjekk ved lukking eller frå knappen <strong>Tilbakemelding</strong>. Blir ikkje sendt om saka er open igjen eller i papirkorga når påminninga forfell. Bruker e-postmalen <strong>KTI-påminning</strong> viss du har ein, elles undersøkingsmalen på nytt. Blir sendt av bakgrunnsjobben <em>Utsette tilfredsheitsundersøkingar og påminningar</em>. Å slå dette på gir ikkje påminning om gamle undersøkingar: berre dei der påminninga forfell frå no av.',
            'one_per_ticket' => 'Éi undersøking per sak',
            'one_per_ticket_help' => 'Er ho på, får ei sak som blir opna att og lukka igjen, berre ei ny undersøking når ein analytikar utløyser henne manuelt &mdash; det hindrar at ei ustabil sak spammar med undersøkingar.',
            'in_channel' => 'Spør chat-kundar i chatten deira',
            'in_channel_help' => 'Ein kunde som skreiv inn på WhatsApp, Telegram, Slack, Teams eller Mattermost, blir spurd i den chatten &mdash; med knappar der appen har dei, &ldquo;svar 1 til 5&rdquo; der han ikkje har det &mdash; i staden for på e-post. WhatsApp berre medan 24-timarsvindauget er ope; elles, og viss ei chatmelding feilar, blir e-postundersøkinga brukt.',
            'scale_stars' => 'Stjerner',
            'scale_emojis' => 'Emojiar',
            'scale_help' => 'Begge alternativa lagrar det same talet frå 1 til 5, så oversikter og gjennomsnitt verkar likt uansett &mdash; dette endrar berre korleis sjølve undersøkingssida ser ut.',
