    'help' => [
        'case' => [
            'nav' => 'Saksrapportar',
            'heading' => 'Saksrapportar',
            'intro' => 'Når ein granskar eller ein revisor spør korleis ei sak vart handtert, samlar <strong>Eksporter</strong> saka, samtalen og oppgåvene som gjorde jobben i eitt dokument som kan skrivast ut - så ingen treng å kopiere det ut for hand.',
            'step1' => '<strong>Opne saka</strong> og vel <strong>Eksporter</strong> i verktøylinja (under <strong>Meir</strong> når lesefeltet er smalt). Rapporten opnar seg i ei ny fane. For ei oppgåve utan sak brukar du dokumentknappen øvst i oppgåvevindauget i staden.',
            'step2' => '<strong>Kryss av for kva som skal med</strong> i panelet til venstre. Rapporten teiknast på nytt medan du kryssar av, og ingenting blir registrert medan du vel.',
            'step3' => '<strong>Vel oppsett</strong>: ei framside, ei innhaldsside, kvar seksjon på ei ny side og ei topptekst med sidetal.',
            'step4' => '<strong>Skriv ut</strong>, og vel så <em>Lagre som PDF</em> i utskriftsvindauget. Fjern avkryssinga for nettlesaren sin eigen <em>Topp- og botntekst</em> - rapporten skriv ut sine eigne.',
            'contents' => '<strong>Kva som kjem med:</strong> ei oversikt over saka (med dei eigendefinerte felta, lenkja ressursar, konfigurasjonselement og relaterte saker); alle meldingar, eldst først; notata; sjekklistene til saka; kvar lenkja oppgåve med deloppgåver, sjekklisteresultat og unntaksnotat, skjemasvar, prosedyrane som vart følgde, oppfølgingar og kommentarar; historikken til saka og til kvar oppgåve; og ein indeks over dokumenta og e-postvedlegga, med det digitale fingeravtrykket FreeITSM registrerte for kvart dokument.',
            'layout' => '<strong>Oppsett:</strong> innhaldssida listar opp kvar seksjon og oppgåve, og kvar oppføring er ei lenke i den lagra PDF-en. Topptekst og sidetal (<em>Side 3 av 12</em>) krev ein oppdatert Chrome eller Edge; andre nettlesarar skriv ut rapporten utan dei.',
            'who' => '<strong>Kven ser kva:</strong> rapporten viser berre det du kunne sjå på skjermen. Oppgåver, ressursar, konfigurasjonselement, relaterte saker, dokument og skjemasvar blir kvar for seg kontrollerte etter sin eigen regel, og alt du ikkje har lov til å sjå blir <em>talt</em> - aldri namngitt - så lesaren veit at noko er utelate. <strong>Interne notat blir utelatne med mindre du kryssar dei av</strong>, fordi ein rapport vanlegvis forlèt teamet.',
            'recorded' => '<strong>Kva som blir registrert:</strong> utskrift skriv ei <em>Saksrapport</em>-linje i revisjonssporet til saka med kven som skreiv ut og kva seksjonar han dekte. Førehandsvising og endring av vala registrerer ingenting.',
            'note' => 'Ein saksrapport er ein kopi av oppføringa, ikkje ei attgjeving: ingenting blir omskrive eller samandrege, bilete inni e-postar blir ikkje gjengitt, filer blir lista opp i staden for å takast med, og berre historikk FreeITSM faktisk registrerte kjem med. Ein seksjon som ikkje kan lesast, seier frå om det i raudt i staden for å sjå tom ut.',
        ],
        'workspace' => [
            'nav' => 'Arbeidsflate og saktabell',
            'heading' => 'Arbeidsflata og saktabellen',
            'intro' => 'To andre måtar å arbeide gjennom saker på, begge valfrie. <strong>Arbeidsflata</strong> legg ei sak til rette for arbeid i staden for lesing. <strong>Saktabellen</strong> viser saklista som ein tabell du kan filtrere, sortere og lagre.',
            'ws_title' => 'Arbeidsflata',
            'ws_what' => 'I arbeidsflata ligg eigenskapane til saka i ei kolonne til venstre, og <strong>Samtale</strong>, <strong>Arbeid</strong> (sjekklister, skjema og lenkja oppgåver), <strong>Lenker</strong>, <strong>Tid og SLA</strong> og <strong>Historikk</strong> er faner ved sida av. Verktøylinja og alle kontrollane er dei same som lesefeltet har - berre plasseringa er ny. <strong>Sjekklista</strong> til saka viser kvart steg med avkryssingsboksen på fana Arbeid; <strong>Fell saman</strong> viser berre neste steg (blir hugsa i nettlesaren din), og <strong>Opne i eige vindauge</strong> opnar henne framleis for seg sjølv.',
            'ws_admin' => '<strong>Ein administrator slår henne på</strong> under <strong>Saker &rarr; Innstillingar &rarr; Generelt &rarr; Saksarbeidsflate</strong>: <em>Av</em> (standard), <em>Berre saker gjorde om til arbeidsflate</em> eller <em>Alle saker</em>.',
            'ws_make' => '<strong>Gjere ei sak om til arbeidsflate:</strong> i det midtre valet opnar du saka og vel <strong>Meir &rarr; Lag arbeidsflate</strong> (og <strong>Tilbake til lesefeltet</strong> for å angre). Valet høyrer til saka, så alle som arbeider med henne ser henne på same måte, og det blir ført i historikken til saka.',
            'ws_own' => '<strong>Ditt eige val:</strong> når ho er slått på, slår <strong>Bruk arbeidsflata</strong> i filtermenyen til lista, eller under <strong>System &rarr; Innstillingar</strong>, henne av berre for deg. Ei sak som er gjord om til arbeidsflate viser då eit lite <em>Arbeidsflate</em>-merke, så du veit at ein kollega arbeider med henne på den måten.',
            'ws_checklist' => '<strong>Sjekklistene til saka viser kvart steg:</strong> på fana <strong>Arbeid</strong> viser ei sjekkliste alle stega med avkryssingsboksar. <strong>Fell saman</strong> krympar henne til berre neste steg, slik lesefeltet viser henne, og <strong>Utvid</strong> hentar resten attende - nettlesaren din hugsar kva du valde. <strong>Opne i eige vindauge</strong> opnar framleis den fullstendige sjekklista i eit vindauge.',
            'ws_tasks' => '<strong>Lenkja oppgåver opnar seg på staden:</strong> klikk på ei oppgåve på fana <strong>Arbeid</strong>, så opnar redigeringa hennar seg der - med sjekklister, skjema, prosedyrar, deloppgåver, kommentarar og dokument. <strong>Opne separat</strong> opnar henne i eit eige vindauge som før; Ctrl-klikk gjer det same. Du må ha tilgang til Oppgåver for å redigere henne.',
            'ws_safe' => '<strong>Ingenting halvskrive går tapt:</strong> viss du går til ei anna sak, eller slår av arbeidsflata, med eit svar, eit notat eller ei oppgåveendring som ikkje er lagra, blir du spurd først, og systemet ventar på alt som framleis blir lagra.',
            'tb_title' => 'Saktabellen',
            'tb_what' => 'Vel <strong>Tabell</strong> i staden for <strong>Meldingar</strong> i handlingsrada øvst i Saker (eller under <strong>System &rarr; Innstillingar</strong>). Mappa du er i blir filteret til tabellen; vel kolonnar, filtrer og sorter dei, søk, og gå gjennom lista 25, 50 eller 100 saker om gongen. <strong>Lagre visning</strong> tek vare på eit oppsett for deg sjølv, teamet ditt eller alle.',
            'tb_remember' => 'Tabellen hugsar visinga du sist valde og opnar med henne neste gong, i kva som helst nettlesar - til du vel ei anna eller brukar <strong>Nullstill</strong>, og då opnar han med standardvisinga di igjen. Når han blir opna frå ei mappe som alt avgrensar lista - ei avdeling, eit team, ein analytikar, ein status eller Ikkje tildelt - gjeld mappa, og berre ei standardvising erstattar henne.',
            'tb_same' => 'Klikking, Ctrl- og Shift-klikking, høgreklikking, å dra til ei mappe og massehandlingane fungerer som i meldingslista, og tabellen viser aldri ei sak som lista ikkje ville ha vist.',
            'tb_export' => '<strong>CSV-eksport:</strong> CSV-knappen eksporterer <em>alle</em> saker som samsvarar, ikkje berre sida, med kolonnane du viser. Kven som kan bruke han blir sett under <strong>Saker &rarr; Innstillingar &rarr; Generelt &rarr; Kven kan eksportere saklista</strong>: berre administratorar (standard), alle med Saker, eller ingen. Knappen blir ikkje vist for nokon han ikkje er open for.',
            'tb_columns' => '<strong>Kven ei sak er for:</strong> kolonnane <strong>Bestillar</strong> og <strong>E-post til bestillar</strong> viser personen saka vart oppretta for og e-postadressa hans. Dei er skjulte til du kryssar dei av under <strong>Kolonnar</strong>; begge kan sorterast, og begge kjem med i CSV-eksporten når dei blir viste.',
        ],
        'page_title' => 'Servicedesk - Rettleiing for saker',
        'sidebar_title' => 'Rettleiing',
        'hero_title' => 'Rettleiing for saksmodulen',
        'hero_sub' => 'Registrer, følg opp og løys IT-førespurnader frå éin mappebasert innboks &mdash; laga for servicedeskteam.',
        'nav' => [
            'overview' => 'Oversikt',
            'inbox' => 'Innboksen',
            'working_with_tickets' => 'Arbeid med saker',
