        'overview' => [
            'heading' => 'Oversikt',
            'intro' => 'Saksmodulen er kjernen i IT-servicedesken din. Han gjev eit kjent grensesnitt i stil med eit e-postprogram for å handtere førespurnader, hendingar og tenesteoppgåver. Saker kjem inn frå sluttbrukarar via e-post eller blir oppretta manuelt, og analytikarar jobbar seg gjennom dei ved hjelp av mapper, prioritetar og SLA-klokker &mdash; alt du treng for å levere rask IT-støtte.',
            'card_inbox_title' => 'Innboks',
            'card_inbox_body' => 'Ein mappebasert innboks modellert på eit e-postprogram. Bla gjennom mappene Mine saker, Ikkje tildelt, Alle opne og Lukka. Klikk ei sak for å opne eit lesefelt med alle detaljar, historikk og handlingar.',
            'card_dashboard_title' => 'Oversikt',
            'card_dashboard_body' => 'Bygg ei personleg oversikt med tilpassbare Chart.js-element. Visualiser saksmengder, responstider, fordeling på kategoriar og arbeidsmengd per analytikar med stolpe-, kake-, smultring- og linjediagram.',
            'card_calendar_title' => 'Kalender',
            'card_calendar_body' => 'Sjå saker i eit kalenderrutenett ut frå når dei vart oppretta, forfell eller vart løyste. Oppdag forfalne saker raskt og planlegg veka ved å sjå heile saksbiletet på éin gong.',
            'card_rota_title' => 'Vaktliste',
            'card_rota_body' => 'Planlegg analytikarskift og beredskapsvakter. Sjå kven som er tilgjengeleg når, planlegg dekning for helger og heilagdagar, og sørg for at inga sak blir liggjande.',
        ],
        'inbox' => [
            'heading' => 'Innboksen',
            'intro' => 'Innboksen er hovudarbeidsflata for analytikarar. Han brukar ei oppdeling i tre felt &mdash; mapper til venstre, saksliste i midten og eit lesefelt til høgre &mdash; slik at du kan triagere og svare utan å forlate sida.',
            'p_live' => '<strong>Han held seg oppdatert av seg sjølv.</strong> Kvart minutt sjekkar innboksen postkassene dine og ser etter noko nytt på sakene du kan sjå &mdash; ein e-post som er henta i bakgrunnen, ei melding frå WhatsApp, Telegram, Slack, Teams eller Mattermost, eit svar frå ein kollega &mdash; og når noko har kome inn, blir lista og mappetala oppdaterte av seg sjølve, akkurat som med oppdateringsknappen. Saka du les og svaret du skriv blir ikkje rørte.',
            'p_folders' => 'Mappepanelet organiserer saker i logiske grupper. Kvar mappe viser eit tal på ulesne, så du får auge på nytt arbeid med det same:',
            'field_my' => '<strong>Mine saker</strong> &mdash; saker som er tildelte deg. Dette er den personlege køen din og den beste staden å starte dagen.',
            'field_unassigned' => '<strong>Ikkje tildelt</strong> &mdash; saker som har kome inn, men som enno ikkje har ein analytikar. Plukk saker herifrå for å ta eigarskap.',
            'field_all_open' => '<strong>Alle opne</strong> &mdash; alle saker som enno ikkje er lukka, uansett kven som eig dei. Nyttig for leiarar og teamleiarar som følgjer med på den samla mengda.',
            'field_closed' => '<strong>Lukka</strong> &mdash; løyste saker. Søk her når du treng å slå opp ei tidlegare løysing eller opne ei sak att.',
            'field_dept' => '<strong>Avdelingsmapper</strong> &mdash; saker grupperte etter avdeling (til dømes IT, HR, økonomi). Avdelingar blir sette opp i Innstillingar og dukkar opp som undermapper automatisk.',
            'switch_heading' => '<strong>Byte mellom gruppering på avdeling og på analytikar</strong>',
            'switch_body' => 'Ein liten tokknappsbrytar øvst i mappepanelet byter mellom to visingar av dei same dataa. Gruppering på <strong>avdeling</strong> (standard) listar saker under kvar avdeling med statusundermapper inni; gruppering på <strong>analytikar</strong> snur det, slik at kvar toppmappe er den personlege køen til ein analytikar, med statusundermapper inni. Mappa <strong>Ikkje tildelt</strong> tilpassar seg kvar vising &mdash; i avdelingsvisinga listar ho saker utan avdeling, i analytikarvisinga saker utan tildelt analytikar &mdash; så du ser alltid kva som må plukkast opp. Valet ditt blir lagra per analytikar, så kvart teammedlem tek vare på visinga dei føretrekkjer frå gong til gong.',
            'folders_hide' => '<strong>Treng du meir plass?</strong> Trykk <strong>[</strong> (når du ikkje skriv), eller <strong>&laquo;</strong> øvst i mappepanelet, for å felle det saman til ei smal stripe; trykk <strong>[</strong> eller klikk på stripa for å få det attende. For å ha det samanfelt kvar gong vel du <strong>Klikk for å opne</strong> eller <strong>Vis ved peiking</strong> for <em>Saker - mapper</em> i Innstillingar &rarr; Visning &rarr; Venstrepanel. Når mappene er samanfelte, opnar dei seg over saklista og lukkar seg att når du vel ei. På ein telefon fungerer mappene som før.',
            'folders_narrow' => '<strong>I eit smalt vindauge</strong> (1100 px breitt eller mindre, som ei nettbrett), startar mappene samanfelte sjølv med <strong>Alltid synleg</strong>, og saklista blir litt smalare, så saka du les får plass. Gjer vindauget breiare, så kjem dei attende.',
            'p_actions' => 'Over saklista har du fire handlingsknappar: <strong>Ny</strong> for å opprette ei sak, <strong>Søk</strong> for å finne saker på nøkkelord, referanse eller bestillar, <strong>Filter</strong> for å avgrense det du ser, og <strong>Oppdater</strong> for å laste den gjeldande mappa på nytt.',
            'filter_body' => 'Knappen <strong>Filter</strong> (trakta) avgrensar mappene og lista saman, uansett korleis dei er grupperte. <strong>Mine</strong> viser berre saker som er tildelte deg, og <strong>Skjul lukka</strong> utelèt alle saker der statusen er markert som lukka. Medan eit filter er på, har trakta ein prikk og ein etikett blir viste ved sida av listetittelen, så du alltid veit at du ikkje ser alt. Når mappene er grupperte etter <strong>Analytikar</strong>, ligg din eigen mappe øverst som <strong>Mine saker</strong> i staden. Søket har sin eigen bryter, <strong>Inkluder lukka saker</strong>, som er på som standard, fordi eit søk som regel er ein jakt på ei gammal sak. Begge vala blir lagra berre for deg.',
            'row_name' => 'Kvar rad viser sakreferansen og deretter eit namn. Som standard er det <strong>personen som melde inn saka</strong>, og det held seg det same gjennom heile levetida til saka. Viss du heller vil sjå kven som sende den siste meldinga &mdash; som blir postkassen din når du har svara &mdash; kan du endre <strong>Namn ved sida av saksnummeret</strong> under <strong>Innstillingar &rarr; Radvising</strong>, der du òg kan skjule namnet og berre la referansen stå att. Den fana er di eiga innstilling: ho endrar ingenting for nokon andre.',
            'tip' => 'Klikk ei sak i lista for å laste henne i lesefeltet. Derifrå kan du oppdatere felt, leggje til kommentarar, svare på e-post eller leggje ved filer &mdash; alt utan å navigere bort frå innboksen.',
        ],
        'live' => [
            'heading' => 'Direkteoppdateringar',
            'body' => 'FreeITSM held skjermen din i takt med alle andre. Når ein kollega endrar ei sak - status, prioritet, eigar eller team, eit svar, eit notat - hentar saklista di og saka du har open seg inn att innan om lag 15 sekund, utan at du må oppdatere. Oppgåvetavla, ei open oppgåve og bjølla fungerer på same måte.',
            'what' => 'Han sjekkar berre medan fana er framme, og hentar seg inn att med det same du kjem tilbake til henne. Ei endring du gjer i ei fane vises i dei andre fanene dine med ein gong.',
            'safe' => 'Han kastar aldri bort det du held på med. Medan du skriv eit svar eller eit notat, skriv i eit felt eller har ei meny open, dukkar nye meldingar framleis opp i samtalen, og resten ventar bak ei lita melding: <strong>Oppdatert av nokon andre nett no &middot; Oppdater</strong>.',
            'setting' => '<strong>Innstillingar &rarr; Direkteoppdateringar</strong> vel kvart 15. sekund (standard), 30 sekund, kvart minutt eller av.',
        ],
        'watch' => [
            'heading' => 'Følgje ei sak',
            'body' => 'Følg ei sak utan å eige henne - ein teamleiar som held auge med ei større hending, eller analytikaren som gav henne frå seg. Følgjarar får beskjed om saka som om ho var deira, gjennom sine eigne varslingsinnstillingar.',
            'how' => '<strong>Følg</strong> i verktøylinja til saka, eller høgreklikk ho i lista og vel <strong>Følg</strong>. Høgreklikk på eit utval for å følgje dei alle. På ei sak du alt følgjer, seier knappen i verktøylinja og høgreklikkmenyen <strong>Slutt å følgje</strong> i staden - eit utval kan følgjast, men ikkje stoppast i éin omgang.',
            'others' => 'Knappen <strong>Følg</strong> viser kven som følgjer. Med skrivetilgang til Saker kan du <strong>leggje til ein kollega</strong> eller ta nokon av; kven som helst kan ta seg sjølv av.',
            'what' => '<strong>Saker &rarr; Innstillingar &rarr; Generelt &rarr; Følgje saker</strong> vel kva følgjarar får høyre om - svar, notat, status, prioritet, omfordeling, SLA-åtvaringar og brot - alt saman med mindre ein administrator fjernar nokre. Ei omfordeling når ein følgjar som «omfordelt», aldri «tildelt deg», og ho har sin eigen bryter i innstillingane til kvar person.',
            'leaver' => 'Ein deaktivert analytikar får aldri beskjed om ei sak han følgjer. <strong>Saker &rarr; Innstillingar &rarr; Generelt &rarr; Når ein følgjar blir deaktivert</strong> avgjer kva som skjer med følgjingane hans: <strong>Stopp</strong> (standard) held dei ute av syne og set dei attende viss analytikaren blir aktivert igjen; <strong>Fjern</strong> tek analytikaren av kvar sak han følgjer når han blir deaktivert.',
            'note' => 'Berre folk som kan sjå ei sak kan følgje henne, og viss dei ikkje lenger kan sjå henne, får dei ikkje meir beskjed om henne. Ingen får beskjed om si eiga endring. Samanslåing flyttar følgjarar til saka som blir att.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Skjema på ei sak',
            'body' => 'Legg ved eit skjema frå Skjema-modulen til ei sak og fyll det ut der - ei førespurnad om ein nytilsett som treng utstyrsskjemaet sitt, eller ei tryggleikshending som treng rapporten sin. Svara blir lagra saman med saka.',
            'switch' => '<strong>Saker &rarr; Innstillingar &rarr; Sjekklister &rarr; Skjema på saker</strong> slår det på (det er av til du gjer det, og Skjema-modulen må vere på òg). Ein <strong>Skjema</strong>-knapp dukkar då opp i verktøylinja til kvar sak, med eit tal for kor mange som er sende inn. I ei arbeidsflate vises skjemaa òg på fana <strong>Arbeid</strong>. Høgreklikk på ei sak, eller eit utval, og vel <strong>Legg til skjema</strong> for å leggje til eitt utan å opne henne.',
            'how' => '<strong>Skjema</strong> opnar lista: <strong>Legg til</strong> vel eit skjema (alltid den nyaste versjonen), <strong>Fyll ut</strong> opnar det i eit vindauge, <strong>Lagre utkast</strong> tek vare på halvferdige svar som kollegaer kan fortsetje på, og <strong>Rett</strong> erstattar ei innsending medan den gamle blir verande i Skjema.',
            'required' => 'Kvart skjema er <strong>Påkravd - hindrar lukking</strong>, <strong>Påkravd - åtvarar ved lukking</strong> eller <strong>Valfritt</strong>. Eit skjema som hindrar må sendast inn før saka kan få ein lukka status; eit som åtvarar spør og registrerer kven som lukka henne likevel.',
            'note' => 'Å fylle ut eit skjema krev skrivetilgang til Skjema og til Saker. Å lese svara krev tilgang til Skjema eller løyvet <strong>Les skjemasvar på saker du kan sjå</strong> (ei rolleinnstilling); alle andre ser kven som sende det inn og når, men ikkje kva dei skreiv. Ei innsending som ei sak er avhengig av kan ikkje slettast frå Skjema. Svara kjem med i saksrapporten og i REST API-et.',
        ],
        'faster' => [
            'heading' => 'Jobb raskare',
            'intro' => 'Fire ting som gjer ein travel morgon handterleg: lagra svar, å handle på mange saker på éin gong, og å leggje samtalar der dei høyrer heime.',
            'templates_heading' => 'Standardsvar',
            'templates_body' => 'Du sender dei same få svara heile tida. Skriv eitt éin gong, og klikk så på <strong>Malar</strong> nede til venstre i svarvindauget for å leggje det inn ved peikaren &mdash; det blir lagt til det du alt har skrive, i staden for å erstatte det. Malar er rik tekst og støttar dei same <code>[merge_code]</code>-plassholdarane som dei automatiske e-postane, så <code>[requester_first_name]</code> blir til det riktige namnet når du set han inn.',
            'templates_team' => '<strong>Teammalar</strong> &mdash; delte med alle, blir sette opp under Innstillingar &rarr; Svarmalar.',
            'templates_mine' => '<strong>Dine eigne</strong> &mdash; lagre eit utkast med <em>Lagre utkastet som mal</em>. Privat for deg, og inga løyve er nødvendig.',
            'templates_tip' => 'Gje ein mal namn etter situasjonen («Skrivar fråkopla &mdash; første steg»), ikkje etter ordlyden. Det er det du kjem til å leite etter klokka ni om morgonen.',
            'select_heading' => 'Velje fleire saker',
            'select_body' => 'Sakslista verkar som Outlook eller Filutforskar. Ingen avkryssingsboksar.',
            'key_click' => 'Klikk',
            'key_click_d' => 'vel éi og opne henne',
            'key_ctrl' => 'Ctrl+klikk',
            'key_ctrl_d' => 'legg til eller fjern éi, lat resten vere',
            'key_shift' => 'Shift+klikk',
            'key_shift_d' => 'vel ein heil blokk frå der du sist klikka',
            'key_kb' => 'Tastatur',
            'key_kb_d' => 'piltastar for å flytte, Shift+piltastar for å utvide, Ctrl+piltastar og mellomrom for å plukke ut spreidde saker, Ctrl+A for alt, Escape for å nullstille',
            'select_actions' => 'Med fleire valde kan du <strong>høgreklikke ei av dei</strong> for å setje status, prioritet, avdeling, type eller tildelt analytikar på alle saman på éin gong &mdash; eller dra heile settet inn i ei mappe. Kva skjermen viser medan fleire er valde, bestemmer du sjølv, i kontomenyen under Innstillingar.',
            'select_tip' => 'Høgreklikkar du ei sak som <em>ikkje</em> er i utvalet ditt, blir utvalet nullstilt og berre den eine saka treft. Det er med vilje &mdash; du kan aldri handle på eit utval du trudde du var ferdig med.',
            'merge_heading' => 'Slå saman duplikat',
            'merge_body' => 'Melde to personar det same avbrotet? Vel sakene, høgreklikk, <strong>Slå saman</strong>. Samtalane blir samla, og har du sett opp ein KI-leverandør, skriv FreeITSM ei kort oppsummering av kva alle spurde om og kva som alt er gjort, slik at den som tek over, slepp å lese fire trådar.',
            'merge_tip' => 'Ingenting blir sletta nokon gong. Saka som vart slått saman inn, tek vare på referansen sin, held fram med å vere søkbar og viser kvar ho vart av &mdash; og ein kunde som svarar på ein gammal e-post om henne, når framleis fram til deg.',
            'split_heading' => 'Dele opp ei sak',
            'split_body' => 'Den motsette jobben. Når nokon tek opp ei ny, urelatert sak midt i ein samtale, klikkar du <strong>Del opp</strong> på den meldinga (eller høgreklikkar meldingsoverskrifta). Ho blir flytt til ei ny sak, eventuelt med alle nyare meldingar med seg, og den opphavlege tek vare på ein markør som viser kvar dei vart av.',
            'split_tip' => 'Gje den nye saka eit ordentleg emne. Standarden er emnet til den flytte meldinga, som regel eit «SV:» på det <em>gamle</em> problemet.',
            'undo_heading' => 'Ombestemt deg',
            'undo_body' => 'Begge delar kan angrast frå banneret på saka. Å angre ei <strong>oppdeling</strong> blir avvist når nokon har svart på den nye saka, lagt til eit notat eller ført tid &mdash; du får nøyaktig beskjed om kva som står i vegen. Å angre ei <strong>samanslåing</strong> gjev saka tilbake meldingane, notata og den førte tida si og opnar henne att nøyaktig slik ho var, men svar som er skrivne på den andre saka etter samanslåinga, blir verande der.',
        ],
        'working' => [
            'heading' => 'Arbeid med saker',
            'intro' => 'Kvar førespurnad følgjer eit livsløp: ho blir oppretta, triagert, jobba med og løyst til slutt. Saksmodulen gjev deg verktøya til å handtere kvart steg effektivt, frå første registrering til lukking.',
            'creating_heading' => '<strong>Opprette ei ny sak</strong>',
            'step1' => '<strong>Klikk Ny</strong> &mdash; opne vindauget for ny sak frå verktøylinja i innboksen. Fyll inn namnet og e-postadressa til innmeldaren, slik at dei kan få oppdateringar.',
            'step2' => '<strong>Set emnet</strong> &mdash; skriv ei tydeleg og kortfatta oppsummering av problemet. Dette blir vist i sakslista og i eventuelle e-postvarsel som blir sende til sluttbrukaren.',
            'step3' => '<strong>Vel avdeling, type og prioritet</strong> &mdash; vel rett avdeling, sakstype (til dømes hending eller tenesteførespurnad) og prioritetsnivå. Desse felta styrer SLA-klokker og rutingsreglar.',
            'step4' => '<strong>Legg til skildringa</strong> &mdash; gjev alle detaljar om problemet i rik-tekst-editoren. Ta med korleis det kan gjenskapast, feilmeldingar og annan relevant samanheng den som skal løyse saka, treng.',
            'step5' => '<strong>Lagre</strong> &mdash; saka blir oppretta med eit unikt referansenummer og dukkar opp i rett mappe. SLA-klokka startar med det same ut frå prioriteten.',
            'editing_heading' => '<strong>Redigere og handtere saker</strong>',
            'editing_body' => 'Når ei sak først finst, kan du oppdatere alle felt frå lesefeltet. Viktige felt er mellom anna:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Følg saksforløpet: Ny, Open, Under arbeid, Ventar, Løyst, Lukka',
            'card_priority_title' => 'Prioritet',
            'card_priority_body' => 'Set hastegrad og omfang: Kritisk, Høg, Middels, Låg. Kvart nivå har sitt eige SLA-mål',
            'card_category_title' => 'Kategori',
            'card_category_body' => 'Klassifiser problemtypen: Maskinvare, Programvare, Nettverk, Tilgang, Generelt. Nyttig for rapportering',
            'card_analyst_title' => 'Tildelt analytikar',
            'card_analyst_body' => 'Personen som har ansvaret for å løyse saka. Ny tildeling blir logga i aktivitetssporet',
            'card_enduser_title' => 'Sluttbrukar',
            'card_enduser_body' => 'Personen som melde inn førespurnaden. Slå opp på namn eller e-post for å kople til eit eksisterande brukarkort',
            'card_dept_title' => 'Avdeling',
            'card_dept_body' => 'Rut saker til rett team. Avdelingar styrer mappegruppering og filter på oversikta',
            'flow_new' => 'Ny',
            'flow_in_progress' => 'Under arbeid',
            'flow_resolved' => 'Løyst',
            'flow_closed' => 'Lukka',
            'triage_heading' => '<strong>Triage med dra og slepp</strong>',
            'triage_body' => 'Du treng ikkje å opne ei sak for å triagere henne. Dra ei rad frå sakslista inn i ei mappe for å oppdatere felt i éi rørsle:',
            'triage_dept' => '<strong>Avdelingsvising</strong> &mdash; slepp på ei avdelingsmappe for å flytte saka dit, slepp på ei statusundermappe under ei avdeling for å oppdatere begge delar på éin gong, slepp på <strong>Ikkje tildelt</strong> for å fjerne avdelinga.',
            'triage_analyst' => '<strong>Analytikarvising</strong> &mdash; slepp på mappa til ein analytikar for å setje den analytikaren som eigar (set både <code>assigned_analyst_id</code> og <code>owner_id</code>, så Eigar-feltet i lesefeltet blir halde i takt), slepp på ei statusundermappe for å oppdatere begge delar, slepp på <strong>Ikkje tildelt</strong> for å fjerne tildelinga.',
            'triage_spring' => '<strong>Fjørbelasta mapper</strong> &mdash; hald musepeikaren over ei samanslegen mappe medan du dreg, så opnar ho seg automatisk (som i Outlook), slik at kvar underliggjande status er innan rekkjevidde utan at du må sleppe først.',
            'fullscreen_heading' => '<strong>Fullskjermvising</strong>',
            'fullscreen_body' => 'Når du treng å konsentrere deg om éi einskild sak &mdash; ein lang samtale, ei samansett endring, eller eit grundig svar som skal skrivast &mdash; byter du til fullskjermvising. Mappelista og sakslista forsvinn, samtalen fyller heile breidda, og eigenskapane (Avdeling, Type, Status, Kjelde, Løyst ved første kontakt, IT-opplæring, Eigar) blir flytte til eit loddrett sidefelt til høgre.',
            'fullscreen_max' => '<strong>Maksimer-ikonet</strong> &mdash; eit lite ikon heilt til høgre på emnelinja til saka. Klikk for å gå til fullskjerm; klikk att for å gå tilbake til visinga med tre felt.',
            'fullscreen_dbl' => '<strong>Dobbeltklikk ei rad</strong> &mdash; dobbeltklikk ei sak i lista for å opne henne direkte i fullskjerm, den same «opne denne ordentleg»-rørsla som i Outlook.',
            'fullscreen_sticks' => '<strong>Blir verande mellom val</strong> &mdash; når du først er i fullskjerm, blir du der sjølv om du byter til neste sak. Lastar du sida på nytt (F5) utan ei vald sak, går du tilbake til standardvisinga med tre kolonnar, så du kan ikkje bli sitjande fast med mappelista skjult.',
            'fullscreen_back' => '<strong>Tilbake</strong> &mdash; linja over saka viser referansen hennar og ein <strong>Tilbake</strong>-knapp, som tek deg rett attende til lista nøyaktig slik du forlét henne, med tastaturet attende på lista - så pilene flyttar mellom saker og Enter opnar neste med ein gong. <strong>Escape</strong> gjer det same, så snart eit vindauge eller ei meny som låg over saka er lukka. Ingen av dei slår av fullskjerm: den neste saka opnar seg framleis i fullskjerm (krympeikonet er bryteren), og når du går attende til saka du forlét, ligg svaret du hadde starta framleis der.',
            'fullscreen_keys' => '<strong>Tastane rullar saka</strong> &mdash; i fullskjerm rullar piltastane, Page Up / Page Down og mellomrom samtalen, ikkje den skjulte saklista. I eit bilete- eller PDF-vindauge rullar dei det vindauget. I den vanlege visinga med tre felt klikkar du i saka, så rullar tastane henne òg; klikk på lista for å gå attende til å flytte mellom saker.',
            'viewer_heading' => '<strong>Bilete og PDF-ar opnar seg over saka</strong>',
            'viewer_body' => 'Klikk på eit bilete eller ein PDF som er lagd ved eit notat, eller på eit i <strong>Vedlegg</strong>-lista til saka (miniatyrbiletet eller rada), så opnar det seg i eit vindauge oppå saka &mdash; den same visaren som i Filer-modulen. Saka blir ståande nøyaktig der ho var under.',
            'viewer_window' => '<strong>Flytt og endre storleik</strong> &mdash; dra tittellinja for å flytte vindauget og ei kant eller eit hjørne for å endre storleik; dobbeltklikk på tittellinja, eller dra henne til toppen av skjermen, for å fylle skjermen. Biletet eller PDF-en tilpassar seg når vindauget endrar storleik, til du zoomar inn eller ut sjølv &mdash; <strong>Tilpass</strong> gir det attende. Opne fleire, så ligg dei side om side.',
            'viewer_close' => '<strong>Lukk det</strong> &mdash; &times; i tittellinja, eller <strong>Escape</strong> (som lukkar vindauget som er framst). <strong>Last ned</strong> lagrar fila. På ein telefon opnar fila seg i fullskjerm med ein Tilbake-knapp.',
            'viewer_other' => '<strong>Andre filer</strong> &mdash; Word-dokument, rekneark og alt anna blir framleis lasta ned eller opna i ei ny fane, som før. For å opne biletet eller PDF-en til eit notat i ei ny fane i staden, Ctrl-klikk på det.',
            'paste_heading' => '<strong>Lim inn eit skjermbilete i eit notat</strong>',
            'paste_body' => 'Kopier eit skjermbilete, klikk i boksen <strong>Legg til notat</strong> og trykk <strong>Ctrl+V</strong>. Biletet kjem inn der markøren står, med teksten din før og etter, og blir ståande på den plassen etter at notatet er lagra. Klikk på det for å opne det i visaren. <strong>Backspace</strong> fjernar det før du lagrar.',
            'paste_shared' => '<strong>Delte notat deler bileta sine</strong> &mdash; bestillaren ser dei i portalen, på staden. På eit internt notat er dei like private som notatet.',
            'paste_save' => '<strong>Ingenting blir teke vare på før du trykkjer Lagre</strong> &mdash; lukk boksen, så forsvinn bileta med han. Viss eit bilete blir avvist, blir ikkje notatet lagra heller, grunnen blir vist, og teksten din står framleis i boksen.',
            'paste_text' => '<strong>Tekst blir verande tekst</strong> &mdash; å lime inn frå Word, ei nettside eller Excel set inn orda utan formateringa. Knappen <strong>Legg ved</strong> fungerer framleis for alle andre filer.',
            'rightclick_heading' => '<strong>Høgreklikk for raske handlingar</strong>',
            'rightclick_body' => 'Høgreklikk ei sak i lista for å opne ein snøggmeny. Menyen viser saksreferansen øvst, så du veit kva du handlar på, og kvar handling gjeld saka du høgreklikka, <em>utan</em> å endre det som er ope i lesefeltet &mdash; nyttig når du les sak A og må triagere sak B utan å miste plassen din.',
            'rightclick_status' => '<strong>Set status &rarr;</strong> &mdash; ein undermeny som listar alle aktive statusar med fargeprøven sin. Eit hakemerke blir vist ved den gjeldande verdien dersom du høgreklikkar saka du har open. Valet oppdaterer saka med det same, skriv ei oppføring i revisjonssporet, oppdaterer mappeteljingane og synkroniserer statuslista i lesefeltet der det er aktuelt.',
            'rightclick_priority' => '<strong>Set prioritet &rarr;</strong> &mdash; same mønsteret, henta frå oppslaget over aktive prioritetar, med fargen til kvar av dei som fargeprøve. Den første rada er eit <em>(ingen prioritet)</em>-val for å fjerne tildelinga (prioritet kan vere tom).',
            'rightclick_assign' => '<strong>Tildel til &rarr;</strong> &mdash; ein undermeny som listar alle innlasta analytikarar med ei grå initialbrikke, pluss ei <em>(ikkje tildelt)</em>-rad øvst for å fjerne tildelinga. Valet set både <code>assigned_analyst_id</code> OG <code>owner_id</code>, så Eigar-feltet i lesefeltet blir halde i takt.',
            'rightclick_cmdb' => '<strong>Kople CMDB-objekt &hellip;</strong> &mdash; opnar ein veljar som søkjer medan du skriv. Klikk eit treff for å kople det, og hald fram med å plukke &mdash; feltet blir tømt og får fokus att til det neste, og ein «Nyleg kopla»-logg inne i vindauget viser den løpande lista di med grøne hakemerke.',
            'rightclick_time' => '<strong>Før tid &hellip;</strong> &mdash; opnar eit vindauge med minutt + ein dato- og tidsveljar (som står på «no», så du òg kan tilbakedatere) + eit valfritt notatfelt.',
            'rightclick_more' => '<strong>Legg ved sjekkliste &rarr;</strong>, <strong>Legg til skjema &rarr;</strong> og <strong>Følg</strong> - legg ved ei sjekkliste (beste treff først), legg til eit skjema, eller følg saka utan å opne henne. På eit utval gjeld dei kvar valde sak, og hoppar over dei som alt har den sjekklista eller det skjemaet.',
            'rightclick_phone' => '<strong>På ein telefon</strong> held du inne på ei sak i eit halvt sekund for å opne den same menyen som eit panel over heile skjermen. Eit val med fleire alternativ &mdash; Set status, Set prioritet, Tildel til &mdash; glir bort til dei, med <strong>Tilbake</strong> for å gå tilbake.',
            'rightclick_tip' => 'Er saka du handlar på via snøggmenyen, tilfeldigvis den same som er open i lesefeltet, blir den aktuelle delen der (status- og prioritetslistene, CMDB-objekta, tidsføringane) oppdatert automatisk når vindauget blir lukka, slik at grensesnittet held seg i takt.',
            'time_heading' => '<strong>Å føre tid</strong>',
            'time_body' => 'Tid brukt på ei sak blir ført i ein eigen <strong>Tidsføringar</strong>-seksjon i lesefeltet, som ligg mellom panelet med kopla CMDB-objekt og notatpanelet. Overskrifta viser den løpande summen (til dømes «Totalt 2t 30m»), og kvar oppføring under viser tida som er brukt, analytikaren, datoen og eventuelle notat du la til.',
            'time_step1' => '<strong>Skjema i linja</strong> &mdash; skriv talet på minutt i talfeltet, ei valfri kort skildring i notatfeltet, og klikk <strong>Legg til</strong>. Den nye oppføringa dukkar opp med det same øvst i lista, med namnet ditt og tidspunktet no.',
            'time_step2' => '<strong>Tilbakedater via høgreklikk</strong> &mdash; treng du å føre tid du gløymde å registrere tidlegare, høgreklikkar du saka i lista og vel <strong>Før tid &hellip;</strong>. Vindauget har ein dato- og tidsveljar, så du kan stemple oppføringa med tidspunktet arbeidet faktisk vart gjort.',
            'time_step3' => '<strong>Slett dine eigne oppføringar</strong> &mdash; ein liten &times;-knapp dukkar opp ved oppføringar du har ført. Klikk han (og stadfest) for å slette mjukt &mdash; rada blir ståande i databasen med <code>is_active = 0</code> for revisjon, men forsvinn frå lista. Du kan ikkje slette oppføringane til andre analytikarar.',
            'time_tip1' => 'Tider blir lagra som reine minutt (45 min, 90 min og så vidare) og viste som <code>45m</code> eller <code>1t 30m</code> i grensesnittet &mdash; finmaska nok for korte fiksar, utan avrundingskvalar med desimaltimar.',
            'time_tip2' => 'Kvar feltendring blir registrert i aktivitetssporet til saka. Du kan alltid sjå kven som endra kva og når, noko som er avgjerande for revisjonskrav og for overlevering mellom analytikarar.',
        ],
        'comments' => [
            'heading' => 'Kommentarar &amp; vedlegg',
            'intro' => 'Aktivitetssporet er hjartet i kvar sak. Det fangar opp kvar handling som blir gjord &mdash; kommentarar, feltendringar, sende e-postar og vedlagde filer &mdash; i ei tidslinje som fortel heile historia om ein førespurnad.',
            'adding_heading' => '<strong>Leggje til kommentarar</strong>',
            'step1' => '<strong>Opne saka</strong> &mdash; klikk ei sak i innboksen for å laste lesefeltet. Bla ned for å sjå heile aktivitetssporet og kommentarfeltet nedst.',
            'step2' => '<strong>Skriv notatet ditt</strong> &mdash; bruk Legg til notat-knappen for å opne kommentareditoren. Notat er interne som standard og synlege berre for analytikarar på servicedesken.',
            'step3' => '<strong>Svar eller vidaresend på e-post</strong> &mdash; bruk Svar- eller Vidaresend-handlingane for å sende ei melding til sluttbrukaren eller ein tredjepart. E-posten blir logga i aktivitetssporet saman med innhaldet i den utgåande meldinga.',
            'subject_note' => '<strong>Emnet</strong> &mdash; Svar og Vidaresend viser emnet, og du kan endre det. Når du vidaresender ei sak til ein ekstern leverandør og svaret hans legg eige nummer til emnet (til dømes <em>#TCK89633 - FW: &hellip;</em>), bruk <strong>Svar</strong> eller <strong>Vidaresend</strong> på <em>den</em> meldinga i samtalen: det startar frå emnet hennar, så oppfølginga di held på nummeret deira og hamnar på saka deira. Kvar melding viser sitt eige emne under avsendaren. Referansen til saka i hakeparentes blir alltid behalden &mdash; viss du tek han ut, blir han sett inn att når du sender, så svar kjem framleis attende til denne saka.',
            'requester_note' => '<strong>Endre bestillar</strong> &mdash; <strong>Endre bestillar</strong>, ved sida av avsendaren øvst i saka, gjer saka til ein annan sin: ein kollega som melde henne inn på vegner av nokon, ein feil ved mottak. Det blir ført i historikken til saka. Når den gamle bestillaren ser ut som den same personen som skriv frå ei anna adresse, blir du tilbode å slå dei saman: dei andre sakene hans flyttar seg òg, og adressa hans blir ei av adressene til den nye personen, så neste e-post frå han hamnar der. Ei <strong>Bestillar</strong>-linje under avsendaren vises når saka er for ein annan enn den som skreiv meldinga. Post frå ei adresse knytt til ein person (Personar &rarr; sida hans &rarr; E-postadresser) er hans, så han lagar aldri ein andre person.',
            'addresses_note' => '<strong>Adresser medan du skriv</strong> &mdash; byrj å skrive i <strong>Til</strong> eller <strong>Kopi</strong>, så føreslår FreeITSM adresser: <strong>servicedesken</strong> til ein leverandør først (sett han på leverandøren i Kontraktar), så leverandørkontaktar, personar i selskapet til saka, og adresser det nyleg er sendt e-post til frå sakene til det selskapet. Bruk piltastane og Enter, eller klikk; vel så mange du vil, eller skriv dine eigne. Ei adresse frå sakene til eitt selskap blir aldri føreslått på sakene til eit anna, og kven ei konfidensiell sak vart send til blir aldri føreslått i det heile.',
            'attachments_note' => '<strong>E-postvedlegg</strong> &mdash; i vedleggslista opnar eit klikk på eit vedlegg det i eit vindauge over saka der filtypen tillèt det: bilete, PDF-ar, Word-dokument, rekneark og CSV-filer, tekst, lyd og video, med ein nedlastingsknapp. Alt anna blir lasta ned. <strong>Lagre i Filer</strong> ved sida av kvart vedlegg - og ved sida av kvar fil på eit notat - kopierer det til ei mappe i Filer. For å leggje ei fil som alt ligg i Filer til saka, bruk <strong>Frå Filer</strong> i vindauget <strong>Legg til notat</strong> (<strong>Frå datamaskin</strong> er knappen ved sida av) - eit vindauge som ein fildialog opnar seg, med mapper til venstre og filene deira til høgre - som ei lenke (opna gjennom Filer, under løyva til mappa, aldri vist i portalen) eller ein kopi, slik Filer &rarr; Innstillingar &rarr; Deling tillèt.',
            'files_heading' => '<strong>Filvedlegg</strong>',
            'files_body' => 'Legg ved skjermbilete, loggar, dokument eller kva som helst støttande fil rett på ei sak. Filer kan dragast inn i sleppsona for vedlegg eller veljast med filutforskaren. Vedlegg blir lagra på tenaren og kopla til aktivitetssporet til saka, så ingenting går tapt.',
            'audit_heading' => '<strong>Revisjonslogging</strong>',
            'export_heading' => '<strong>Saksrapportar</strong>',
            'export_body' => 'For ei gransking eller ein revisor gjer <strong>Eksporter</strong> i verktøylinja til saka om saka og oppgåvene hennar til éin rapport som kan skrivast ut - sjå <a href="#case-reports">Saksrapportar</a>.',
            'audit_body' => 'Aktivitetssporet registrerer kvar handling automatisk, utan at analytikaren må gjere noko. Når ein prioritet blir endra frå Middels til Høg, blir både den gamle og den nye verdien fanga opp. Når ei sak blir tildelt på nytt, blir både den førre og den nye analytikaren logga. Dette gjev ein fullstendig historikk som ikkje kan tuklast med, som tilfredsstiller ITIL-krav til revisjon og hjelper leiarar med å forstå korleis saker blir handterte.',
            'tip' => 'Når du svarar på e-post, kan du leggje til kopimottakarar og leggje ved filer i den same handlinga. Heile e-postsamtalen blir tråda inn i aktivitetssporet til saka, slik at all kommunikasjon blir halden på éin stad.',
        ],
        'ai' => [
            'heading' => 'KI-verktøy',
            'intro' => 'To Claude-drivne funksjonar ligg inne i saksarbeidsflyten: <strong>Opprydding i svar</strong> skriv eit grovt utkast om til ein ordentleg formatert e-post, og <strong>Spør KI-en</strong> søkjer i kunnskapsbasen på naturleg språk ved hjelp av samanhengen i saka.',
            'cleanup_heading' => '<strong>Opprydding i svar &mdash; ✨-knappen i svareditoren</strong>',
            'cleanup_body' => 'Skriv eit raskt, grovt utkast i eit svar (eller berre punkt som *«må starte utskriftstenesta på nytt, ta skjermbilete til dei»*) og klikk <strong>✨ Rydd opp</strong>-knappen. Claude skriv det om til ein ordentleg formatert e-post &mdash; legg til ei <em>Hei [namn],</em>-helsing frå innmeldaren, rettar grammatikken, brukar den innstilte tonen og avsluttar med <em>Med venleg helsing,</em>. Instruksjonen er stramma inn, så han vil IKKJE finne på tekniske detaljar, dikte opp orsakingar eller fylle på med meir enn det du skreiv.',
            'cleanup_streams' => '<strong>Strøymer direkte</strong> &mdash; omskrivinga dukkar opp i editoren etter kvart som Claude lagar henne (inga venting framfor ein snurrande sirkel).',
            'cleanup_undo' => '<strong>Angre-lenkje i 30 s</strong> &mdash; i tilfelle Claude øydelegg omskrivinga, dukkar ei lita <em>Angre</em>-lenkje opp under editoren i 30 sekund etter at omskrivinga er ferdig, og gjenopprettar det opphavlege utkastet.',
            'cleanup_tone' => '<strong>Per tone</strong> &mdash; tre førehandsinnstilte tonar som blir sette opp under <strong>Innstillingar &rarr; Opprydding i svar</strong>: <em>Venleg</em> (standard), <em>Formell</em>, <em>Kortfatta</em>. Vel den som passar husstilen til teamet ditt.',
            'cleanup_key' => '<strong>Eigen API-nøkkel</strong> &mdash; ein Anthropic-nøkkel åtskild frå KI-funksjonane for RFP, kunnskap og arbeidsflyt, slik at bruken blir vist som si eiga linje i faktureringsoversikta hos Anthropic. Blir sett opp under <strong>Innstillingar &rarr; Opprydding i svar</strong>.',
            'cleanup_prompt' => '<strong>Din eigen prompt</strong> &mdash; <em>Saker &rarr; Innstillingar &rarr; Opprydding av svar</em> viser systemprompten, og du kan endre henne. Kvar lagra versjon blir teken vare på under <em>Historikk</em>: <em>Gjenopprett</em> set ein tidlegare attende, og <em>Nullstill</em> går attende til den innebygde prompten.',
            'cleanup_tip' => 'Opprydding passar best til dei rutinemessige svara i stil med «eg prøvde dette, prøv X». Lange og nyanserte meldingar vil du skrive sjølv &mdash; KI-en er god på struktur, men kjenner ikkje ditt spesifikke miljø.',
            'ask_heading' => '<strong>Spør KI-en &mdash; 🤖-knappen i verktøylinja på saka</strong>',
            'ask_body' => 'Klikk <strong>Spør KI-en</strong>-knappen (🤖) i verktøylinja på saka for å opne eit pratepanel som glir inn og som kjenner emnet, teksten og samanhengen i lesefeltet på den opne saka. Still spørsmål som *«har vi sett dette før?»* eller *«kva er den vanlege løysinga på denne feilen?»*, så søkjer det semantisk i <a href="../knowledge/" style="color:#0078d4;">kunnskapsbasen</a> (via Claude + OpenAI-vektorar) og svarar med relevante artiklar, med direkte lenkjer for å opne dei.',
            'ask_context' => '<strong>Kjenner samanhengen</strong> &mdash; panelet veit kva for ei sak du ser på, så du kan stille generelle spørsmål, og det finn ut av den relevante samanhengen.',
            'ask_linked' => '<strong>Kopla artiklar</strong> &mdash; forslaga kan klikkast og opnar den aktuelle kunnskapsartikkelen i ei ny fane.',
            'ask_shared' => '<strong>Delt med kunnskapsmodulen</strong> &mdash; KI-en brukar same nøkkel og modell som KI-søket i Kunnskap, så set du det opp éin gong, får du begge delar. Sjå hjelpa til kunnskapsmodulen for oppsettdetaljar.',
        ],
        'csat' => [
            'heading' => 'Kundetilfredsheitsundersøkingar (KTI)',
            'intro' => 'Send innmeldaren ei tilfredsheitsundersøking frå 1 til 5 på e-post når ei sak er løyst, ta imot svaret på ei landingsside utan innlogging, og følg trendar per analytikar på ei eiga analysesid.',
            'modes_heading' => '<strong>To utløysarmåtar &mdash; vel éin</strong>',
            'mode_auto' => '<strong>Automatisk ved lukking</strong> &mdash; undersøkinga blir lagd i kø automatisk når ei sak går over i ein lukka status. Analytikaren treng ikkje å gjere noko &mdash; løysinga driv undersøkinga.',
            'mode_manual' => '<strong>Berre manuelt</strong> &mdash; analytikaren klikkar ⭐ <strong>Tilbakemelding</strong>-knappen i verktøylinja på saka når dei vil spørje. Nyttig når du heller vil avgjere sak for sak om du skal be om tilbakemelding.',
            'starters_note' => '<strong>Saker oppretta av ei Starters &amp; leavers-sak</strong> (eit malsteg oppretta som sak) får inga automatisk undersøking, og bestillaren deira ingen automatiske e-postar, med mindre malen kryssar av for <strong>Send e-post til bestillaren om desse sakene</strong>. Kvar e-post som ikkje blir sendt står i sendelogen til postkassa som hoppa over, med grunnen. Saka viser kva sak ho er for i lenkjene sine.',
            'switch_note' => 'Brukar du ikkje KTI i det heile? Slå det av under <strong>System &rarr; Modular &rarr; Tilgjenge &rarr; Saksfunksjonar</strong>, så forsvinn det: ingen undersøkingar, ingen KTI-side, ingen Be om tilbakemelding-knapp, og gamle undersøkingslenker seier at tilbakemelding ikkje lenger blir samla inn. Ingenting blir sletta.',
            'mode_off' => '<strong>Av</strong> &mdash; funksjonen er slått av; det blir ikkje sendt e-postar med undersøkingar.',
            'modes_choose' => 'Vel under <strong>Saker &rarr; Innstillingar &rarr; KTI</strong>. Den manuelle knappen verkar framleis i <em>automatisk</em> modus &mdash; analytikarar kan be om tilbakemelding på nytt på ei sak som alt er undersøkt, om det trengst.',
            'template_heading' => '<strong>E-postmalen</strong>',
            'template_body' => 'Innhaldet i e-posten med undersøkinga kjem frå den eksisterande fana <strong>E-postmalar</strong> &mdash; opprett ein mal med hendinga <strong>KTI-undersøking</strong> (den nye hendinga ved sida av <em>Sak tildelt</em> / <em>Sak lukka</em>) og legg flettekoden <code>[csat_link]</code> der du vil at vurderingslenkja skal stå. Vanlege flettekodar (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) er tilgjengelege som normalt.',
            'template_tip' => 'Finst det ingen aktiv KTI-mal, nektar <em>Tilbakemelding</em>-knappen med ei tydeleg feilmelding, og den automatiske utløysaren hoppar stille over &mdash; du kan aldri produsere døde undersøkingslenkjer.',
            'survey_heading' => '<strong>Undersøkingssida</strong>',
            'survey_body' => 'Innmeldaren klikkar lenkja i e-posten og landar på ei side utan innlogging med ein veljar frå 1 til 5 pluss eit valfritt kommentarfelt. To visuelle stilar kan veljast under <strong>Innstillingar &rarr; KTI</strong>:',
            'survey_stars' => '<strong>Stjerner</strong> &mdash; klassisk åtferd der dei blir fylte etter kvart som du held over. Held du over stjerne 3, blir 1, 2 og 3 fylte i gull. Klikk for å låse.',
            'survey_emojis' => '<strong>Emojiar</strong> &mdash; 5 andlet 😡 🙁 😐 🙂 😀 startar i gråtonar med 40 % dekkevne; den du held over eller vel, får full farge att i 1,25 &times; storleik. Klikk for å låse.',
            'survey_store' => 'Begge måtane lagrar det same talet frå 1 til 5, så oversikter og gjennomsnitt verkar likt uansett kva for ein stil som er i bruk. Undersøkingslenkja verkar berre éin gong &mdash; når brukaren har sendt inn, avviser den same lenkja eit nytt svar.',
            'chat_heading' => '<strong>Spørje chatkundar i chatten deira</strong>',
            'chat_body' => 'Med <strong>Spør chatkundar i chatten deira</strong> kryssa av blir ein kunde som skreiv inn via WhatsApp, Telegram, Slack, Microsoft Teams eller Mattermost spurd i den chatten i staden for på e-post &mdash; fem knappar på Telegram, Teams og Mattermost, «svar med eitt siffer» andre stader. Svaret deira går inn i dei same resultata som ei e-postundersøking.',
            'chat_rules' => 'WhatsApp blir berre spurd medan 24-timars svarvindauget er ope; utanfor det, eller viss chatmeldinga ikkje kan sendast, blir e-postundersøkinga brukt i staden. Eit siffer tel som vurdering berre rett etter spørsmålet &mdash; i same chat, innan ei veke, og før kunden har skrive noko anna &mdash; så «3» som svar på spørsmålet til ein analytikar blir ståande som ei melding. Av etter oppgradering; på for ein ny installasjon.',
            'analytics_heading' => '<strong>Analysesida</strong>',
            'analytics_body' => 'Klikk ⭐ <strong>KTI</strong>-knappen i navigasjonen (mellom Vaktliste og Innstillingar) for å opne analyseoversikta på <code>tickets/csat/</code>. Tidsrommet kan veljast: 7 / 30 / 90 / 365 dagar.',
            'card_kpi_title' => 'Nøkkeltal',
            'card_kpi_body' => 'Gjennomsnittleg vurdering (av 5), tal på svar, svardel (svara ÷ sende)',
            'card_dist_title' => 'Fordeling av poeng',
            'card_dist_body' => 'Stolpediagram over vurderingane 1–5 med nøyaktige tal og prosentar',
            'card_leader_title' => 'Rangering per analytikar',
            'card_leader_body' => 'Gjennomsnittleg vurdering + tal på svar per analytikar, sortert på snitt synkande. Bruk det til utviklingssamtalar',
            'card_recent_title' => 'Nylege svar',
            'card_recent_body' => 'Vurderingane med dei nyaste først, 25 per side, med fritekstkommentarane og kunden som la dei att, lenkja tilbake til opphavssaka',
            'analytics_filters' => 'Avgrens sida med filtera under overskrifta: eit datoområde <strong>Frå / Til</strong> (i staden for dagknappane), eit <strong>Vurdering</strong>-nivå (Positiv 4-5, Nøytral 3, Negativ 1-2), ein <strong>Analytikar</strong> og ein <strong>Kunde</strong>. Analytikar og kunde avgrensar alle tal på sida; vurderingsnivået avgrensar berre lista over svar, så gjennomsnittet framleis betyr noko. På ein telefon ligg filtera bak knappen <strong>Filter</strong> nede på skjermen. Ei filtrert side kan bokmerkast.',
            'analytics_company' => 'Alle tal følgjer <strong>selskapsbytaren</strong> i toppen: selskapet du har valt, eller alle selskap du kan sjå under <strong>Alle selskap</strong>.',
            'analytics_tip' => 'Tilskrivinga per analytikar overlever at saka blir tildelt på nytt, fordi analytikar-ID-en blir fanga opp på undersøkingsrada i det ho blir send, og ikkje slegen opp i etterkant. Går ei sak frå hand til hand før ho blir lukka, er det analytikaren som faktisk lukka henne, som eig vurderinga.',
            'one_heading' => '<strong>Éi undersøking per sak</strong>',
            'one_body' => 'Er <em>Éi undersøking per sak</em> slått på (standard), får ei sak som blir opna att og lukka igjen, berre ei ny undersøking når ein analytikar utløyser henne manuelt &mdash; det hindrar at ei ustabil sak som stadig går i sirkel, spammar med undersøkingar. Slå det av dersom du vil at kvar lukking skal utløyse ei ny undersøking.',
        ],
        'users' => [
            'heading' => 'Brukarhandtering',
            'intro' => '<strong>Brukarar</strong>-knappen i navigasjonen opnar <code>tickets/users.php</code> &mdash; ein katalog over alle sluttbrukarar (dei som melder inn saker, ikkje analytikarar), saman med sakshistorikken til kvar av dei.',
            'p_intro' => 'Brukarar hamnar i systemet på fire måtar som skjer av seg sjølv &mdash; sjølvregistrering i portalen, ein innkomande e-post frå ein ny avsendar, postkassehentaren, eller arbeidsflytmotoren som opprettar ein frå ei utløyst sak. Det dekkjer dei fleste tilfella, men Brukarar-sida lèt deg òg <strong>opprette på førehand</strong> (til dømes ein nytilsett som snart treng tilgang) og <strong>redigere</strong> eller <strong>slette</strong> eksisterande rader.',
            'add_heading' => '<strong>Legg til brukar</strong>',
            'add_body' => 'Knappen <strong>Legg til</strong> i toppen av brukarlista opnar personredigeringa. Det er den same redigeringa som <strong>Ressursar &rarr; Brukarar</strong> opnar, så ein person blir lagd til og endra på same måte uansett kva skjerm du er på:',
            'add_email' => '<strong>E-post</strong> &mdash; valfritt, fordi folk som loggar inn gjennom ein katalog kanskje ikkje har postkasse; dei blir funne ved innloggingsnamnet i staden. Oppgi anten ei e-postadresse eller eit visingsnamn. Ei adresse må vere unik, og kan ikkje tilhøyre ein analytikar.',
            'add_names' => '<strong>Visingsnamn / føretrekt namn</strong> &mdash; valfritt. Føretrekt namn er det brukaren ser seg sjølv helsa med i e-postar (til dømes <em>«Ed»</em> i staden for <em>«Ed Mozley»</em>).',
            'add_password' => '<strong>Passord</strong> &mdash; valfritt. Lèt du det stå tomt, blir det oppretta ein konto <em>utan passord</em> &mdash; nøyaktig den same tilstanden brukarar som kjem inn via e-post, startar i. Brukaren kan seinare ta over kontoen gjennom registreringsflyten i sjølvbeteningsportalen ved å setje sitt eige passord.',
            'add_details' => '<strong>Stilling, avdeling, kontor, telefon, mobil, tilsett-ID og leiar</strong> &mdash; alt valfritt, og alt skildrar <em>personen</em> og ikkje innlogginga. Verdt å fylle ut: <strong>kontoret</strong> fortel kva stad nokon er på før du går og leitar etter dei, <strong>leiar</strong> registrerer rapporteringslinja (skriv ein del av eit namn for å finne dei), og <strong>tilsett-ID</strong> er koplingsnøkkelen når du avstemmer mot eit lønssystem som aldri har høyrt om ei e-postadresse. Når du importerer frå ein katalog, kjem alle desse ferdig utfylte. Ei CardDAV-adressebok fyller ut alt unntatt tilsett-ID og leiar, som eit kontaktkort ikkje har plass til.',
            'managed_heading' => '<strong>Personar vedlikehaldne ein annan stad</strong>',
            'source_body' => '<strong>Kvar ein person kjem frå</strong> er nemnt i detaljane deira (<em>Detaljar frå: Contoso AD - katalog</em>), og filteret <strong>Kjelde</strong> under søkjefeltet listar berre personane frå éin katalog eller adressebok, eller berre dei som er lagt til i FreeITSM, med eit tal ved sida av kvar. Det dukkar opp så snart nokon er kopla til ei kjelde.',
            'add_book_body' => '<strong>Legg til i adressebok.</strong> Nokon som har sendt e-post finst her, men i inga adressebok. Viss ein administrator har slått på <em>La analytikarar leggje personar til i denne adresseboka</em> (System &rarr; Autentisering, på adresseboka), får den personen ein <strong>Legg til i adressebok</strong>-knapp ved sida av Rediger. Han spør først, og viser kva som kjem på kortet, og lagar så kontakten deira og koplar dei saman &mdash; den same personen, ikkje ein kopi. Han legg ikkje til nokon som adresseboka allereie har e-postadressa til (køyr importen i staden), og han sørgjer for at neste import plukkar opp den nye kontakten, eller tek kortet ut att.',
            'managed_body' => 'Der ein person er importert &mdash; frå LDAP eller Active Directory, eller frå ei CardDAV-adressebok &mdash; er detaljane som kjelda eig <strong>skrivebeskytta</strong>, og modalvindauget gråar dei ut. Kva dei enn kom frå, er det sanninga, og neste import ville overskrive alt som er skrive her, så lagringa blir avvist rett ut i staden for å bli godteken og stille rulla tilbake ein time seinare. <strong>Kva</strong> detaljar det gjeld, kjem an på kjelda: ein katalog eig alle sju, medan ei adressebok eig fem &mdash; ho har ingen stad å lagre eit tilsettnummer eller ei rapporteringslinje, så dei to er framleis dine å fylle ut. Og viss adresseboka har <em>skriv endringar tilbake</em> slått på, er ingen av dei låste: det du skriv, blir sendt til kontaktkortet, så det er ingenting for neste import å rulle tilbake. Alt anna på posten, inkludert selskapet og passordet deira, kan alltid redigerast.',
            'edit_heading' => '<strong>Rediger brukar</strong>',
            'edit_body' => 'Vel ein brukar frå lista, og klikk så på <strong>Rediger</strong> i detaljtoppen. Same redigering, førehandsutfylt. Å lagre utan passord lèt det eksisterande hashet vere urørt; å oppgi eit nullstiller det. Viss leiaren deira er nokon i eit selskap du ikkje kan sjå, seier Leiar-boksen frå om det, og leiaren blir ståande som han er med mindre du vel ein annan.',
            'signin_body' => '<strong>Loggar inn med</strong> viser kva leverandør av eingongspålogging ein person er knytt til. <strong>Fjern kopling</strong> ved sida, etter ei stadfesting, fjernar den lenkja slik at neste innlogging startar på nytt &mdash; for nokon som har flytta til ein annan leverandør, eller vart knytt til feil konto. Det blir ikkje tilbode for folk som blir styrte av ein katalogsynkronisering, som berre ville kopla dei saman igjen.',
            'company_body' => '<strong>Selskap</strong> blir viste når du har fleire enn eitt. For ein ny person finn systemet selskapet ut frå e-postadressa når feltet er tomt; for ein eksisterande person betyr tomt inga selskap, og sakene deira går til sortering.',
            'managers_heading' => '<strong>Leiarar</strong>',
            'managers_body' => 'Ein person kan gjerast til <strong>leiar</strong> i sjølvbetjeningsportalen: dei får ei fane <strong>Teamsaker</strong> som viser sakene til dei dei leier. Det er av til ein administrator slår det på under <strong>System &rarr; Leiarar</strong>, som òg avgjer om leiarar kan svare på eller lukke desse sakene, og kva dei ser av ei konfidensiell sak (ingenting, som standard).',
            'managers_sources' => 'Nokon er leiar på to måtar, begge samstundes: dei er <strong>Leiar</strong> på andre personar sine postar (for hand, eller frå katalogen din), og dei har <strong>leiarlinjer</strong> sette opp for seg. Klikk på <strong>Leiartilgang</strong> ved sida av Rediger for å opne ei side over heile skjermen for den personen, der du kan gi dei alle, bestemte personar, persongrupper, avdelingar eller heile rapporteringslinja deira, og <strong>utelate</strong> folk &mdash; eit unntak vinn alltid, òg over Leiar-feltet. Sida viser kor mange personar dei kan sjå og lister dei opp, rekna ut som om leiarar alt var slåtte på, så du kan sjekke før du slår på. Klikk på nokon i lista for å sjå <strong>kvifor</strong> leiaren kan sjå dei, og korleis du stoppar det.',
            'managers_rules' => 'Ein leiar ser berre folk i sitt eige selskap, aldri seg sjølv, og ingenting i det heile etter at dei har slutta. Avdelingar blir samanlikna på namnet som er skrive på kvar person, så ei avdeling som har fått nytt namn sluttar å samsvare &mdash; sida, og System &rarr; Leiarar, åtvarar om ei avdelingslinje som ikkje samsvarar med nokon. Som standard kan berre administratorar endre leiarlinjer; System &rarr; Leiarar kan opne det for alle som kan redigere personar.',
            'delete_heading' => '<strong>Slett brukar</strong>',
            'delete_body' => '<strong>Slett</strong>-knappen er <strong>trygg mot framandnøklar</strong>: han nektar dersom brukaren er innmeldar på nokon saker eller har rader i <code>users_assets</code>, og gjev ei tydeleg melding: <em>«Kan ikkje slette: denne brukaren er innmeldar på N sak(er). Tildel eller lukk dei sakene først.»</em> Revisjonshistorikken kan aldri brytast i stillheit.',
            'tip' => 'Alle felta i vindauget har autofyllinga til nettlesaren slått av (medrekna <code>autocomplete="new-password"</code> på passordfeltet), slik at analytikaren sine eigne lagra påloggingsopplysningar ikkje blir føreslegne inn i eit skjema som har som einaste føremål å opprette kortet til <em>ein annan</em>.',
            'groups_heading' => '<strong>Grupper</strong>',
            'groups_body' => 'Fana <strong>Grupper</strong> ved sida av <strong>Personar</strong> inneheld namngjevne grupper av personar &mdash; analytikarar og sjølvbetjeningsportal-brukarar saman i same gruppe. Ei gruppe blir laga éin gong her og deretter brukt over heile FreeITSM, så du kan gje ho tilgang til ei kunnskapsmappe eller tildele ho eit opplæringskurs utan å byggje same lista to gonger.',
            'groups_make' => '<strong>Lag ei</strong> med <strong>Legg til</strong> på Grupper-fana: eit namn, og ei skildring som er verdt å fylle ut, fordi neste person må kunne sjå kva gruppa er til for.',
            'groups_add' => '<strong>Legg til personar</strong> ved å søkje etter dei &mdash; det finn analytikarar og portalbrukarar saman, så du treng ikkje vite kva type nokon er.',
            'groups_expiry' => '<strong>Gje eit medlemskap ein sluttdato</strong> der tilgangen er mellombels. Tre ingeniørar på staden i to veker blir lagde inn med ein siste dag og fell automatisk ut av gruppa når han passerer. Eit utgått medlemskap blir ståande på lista, merkt som utgått, så du framleis kan sjå kven som hadde tilgang og til når.',
            'groups_uses' => '<strong>Kva ei gruppe er god for:</strong> å gje tilgang til ei kunnskapsmappe, og å tildele LMS-opplæring til fleire personar samstundes. Endringar i medlemskap gjeld med ein gong &mdash; det er ingenting å bruke om att etterpå.',
            'groups_admin' => '<strong>Alle med Saker-modulen kan sjå gruppene; berre ein administrator kan endre ei.</strong> Å leggje nokon til i ei gruppe kan òg gje dei tilgang til ei avgrensa kunnskapsmappe, så det er ei tildeling av tilgang, ikkje ei arkiveringssak.',
        ],
        'dash' => [
            'heading' => 'Oversikt',
            'intro' => 'Saksoversikta gjev analysar med eitt blikk, i tilpassbare Chart.js-element. Kvar analytikar har sitt eige oppsett, så du kan konsentrere deg om måla som betyr noko for di rolle &mdash; anten det er di eiga arbeidsmengd, gjennomstrøyminga til teamet eller SLA-etterlevinga.',
            'step1' => '<strong>Opne biblioteket</strong> &mdash; klikk Rediger oversikt for å gå inn i redigeringsmodus, og bla så gjennom elementbiblioteket. Vel blant ferdiglaga element, eller lag ditt eige ved å velje ein diagramtype og eigenskapen som skal summerast.',
            'step2' => '<strong>Legg til element</strong> &mdash; klikk +-knappen på eit element i biblioteket for å leggje det til på oversikta di. Det dukkar opp med det same og byrjar å vise ferske data frå saksdatabasen din.',
            'step3' => '<strong>Set det opp</strong> &mdash; klikk tannhjulet på eit element for å tilpasse tittel, diagramtype (stolpe, kake, smultring, linje, stabla stolpe, fleirlinje), filter på tidsrom, filter på avdeling og tidsgruppering (dagleg, vekentleg, månadleg).',
            'step4' => '<strong>Ordne dei</strong> &mdash; dra og slepp element for å endre rekkjefølgja. Oppsettet ditt blir lagra per analytikar, så det står ved lag frå gong til gong.',
            'examples' => 'Vanlege døme på element er: <strong>Saker etter status</strong> (smultringdiagram som viser opne mot løyste mot lukka), <strong>Saker etter prioritet</strong> (stolpediagram over mengd per alvorsgrad), <strong>Vekentleg mengd</strong> (linjediagram som følgjer nye saker over tid) og <strong>Arbeidsmengd per analytikar</strong> (stabla stolpe som viser dei aktive sakene til kvar analytikar).',
            'tip' => 'Bruk filter på tidsrom på einskildelement for å samanlikne dagens resultat med tidlegare periodar. Ei vising av typen «Denne månaden mot førre månad» hjelper deg til dømes å oppdage trendar i saksmengda tidleg.',
        ],
        'cal_rota' => [
            'switch_note' => 'Brukar du ikkje vaktlista? Slå ho av under <strong>System &rarr; Modular &rarr; Tilgjenge &rarr; Saksfunksjonar</strong> - sida, innstillingane hennar og <em>kven har vakt</em> i War Room-boten forsvinn, og ingenting blir sletta.',
            'heading' => 'Kalender &amp; vaktliste',
            'intro' => 'To planleggingsverktøy hjelper teamet ditt med å halde orden: ein sakskalender som viser arbeidsmengda over tid, og ein bemanningsplan for å handtere skift og beredskap.',
            'cal_heading' => '<strong>Kalendervising</strong>',
            'cal_body' => 'Kalenderen plottar kvar sak som har <code>work_start_datetime</code> sett (via høgreklikkvindauget <em>Før tid</em> / <em>Planlegg</em>) som ein farga blokk på det planlagde tidspunktet. Raude blokker er <em>Høg</em> prioritet, grøne er <em>Låg</em>, blå er alt anna. Bruk <em>I dag</em>, pilene <em>&lt;</em> / <em>&gt;</em> og brytaren <strong>Månad / Veke / Dag</strong> til høgre i overskrifta for å navigere &mdash; <em>Førre</em> / <em>Neste</em> flyttar ein månad, ei veke eller ein dag avhengig av kva for ei vising som er aktiv.',
            'cal_scope' => '<strong>Mine eller Alle.</strong> Kalenderen opnar på ditt eige planlagde arbeid, med ein <strong>Alle</strong>-brytar ved sida av visingsknappane; valet ditt blir hugsa. I Alle har kvar sak ein <strong>farge for kven som eig ho</strong>, med ei teikinforklaring som namngjev personane som faktisk er på skjermen, og å peike på ei sak fortel deg kven ho tilhøyrer utan at du treng sjå bort. Ingenting er skjult for nokon &mdash; dette er dei same sakene innboksen allereie listar.',
            'cal_edit' => '<strong>Omorganisere arbeid.</strong> <strong>Dra ei sak</strong> til ein annan dag eller eit anna tidspunkt: i månadsvisning held ho tidspunktet sitt, og i veke- og dagvisning tek ho tidspunktet du slepp ho på, avrunda til næraste kvarter. Lengda endrar seg aldri &mdash; å dra seier <em>start ho då</em>, ikkje <em>gjer ho lengre</em>. Eller <strong>klikk på ei sak</strong> for å opne ho, der du kan endre dato, tidspunkt, varigheit og innstillinga for heile dagen, eller tømme tidsplanen heilt. Kalenderen <strong>oppdaterer seg sjølv kvart nokre sekund</strong>, så noko ein kollega planlegg, dukkar opp utan at du lastar på nytt &mdash; og han held att medan du har ei sak open eller er midt i å dra.',
            'cal_month' => '<strong>Månadsvising</strong> &mdash; det klassiske rutenettet med seks rader og ei stripe med vekedagar øvst; kvar dagcelle viser opptil tre sakspiller med starttidspunktet sitt, pluss ei <em>+N til</em>-lenkje som tek deg til dagsvisinga for den datoen. I dag er utheva.',
            'cal_week' => '<strong>Vekevising</strong> &mdash; mån&ndash;søn langs toppen over ei loddrett tidslinje på 24 timar. Saker blir viste som farga blokker på éin time ved starttidspunktet sitt. Kolonnen for i dag er utheva; vekedagsoverskrifta blir ståande medan timerutenettet rullar.',
            'cal_day' => '<strong>Dagsvising</strong> &mdash; éin høg kolonne for den valde dagen, med den same tidslinja på 24 timar. Saker blir viste som større blokker med <code>saksnummer &mdash; emne</code> og starttidspunkt; klikk ei for å opne detaljane.',
            'rota_heading' => '<strong>Bemanningsplan</strong>',
            'rota_body' => 'Vaktlistesida lèt teamleiarar og leiarar planleggje analytikarskift gjennom veka. Definer normal arbeidstid, tildel beredskapsperiodar, og merk ferie eller fråvær, slik at teamet alltid veit kven som er tilgjengeleg.',
            'rota_step1' => '<strong>Sjå vaktlisterutenettet</strong> &mdash; vaktlista viser analytikarar langs den eine aksen og dagar langs den andre, med skiftblokker som gjev dekninga med eitt blikk.',
            'rota_step2' => '<strong>Legg til eller rediger skift</strong> &mdash; klikk ei celle for å tildele ein skifttype (til dømes Tidleg, Sein, Natt, Beredskap). Endringar blir lagra med det same.',
            'rota_step3' => '<strong>Planlegg framover</strong> &mdash; bla framover veke for veke for å byggje vaktlista i forkant. Slik sikrar du nok dekning i kjende travle periodar, feriar eller opplæringsdagar.',
            'rota_step4' => '<strong>Fyll fleire celler samstundes</strong> &mdash; <strong>høgreklikk</strong> ei celle og vel <em>Kopier</em> for å hente vakta i ho, høgreklikk så ei anna og <em>Lim inn</em>. For meir enn éi celle kan du <strong>dra over ein blokk</strong> av dei (eller ctrl-klikk celler éin om gongen) og lime inn i heile blokka. Å peike på ei <strong>dagoverskrift</strong> lyser opp heile den dagen, og å peike på <strong>namnet til ein analytikar</strong> lyser opp heile veka deira &mdash; høgreklikk kvar av dei og lim inn i alt saman. Der nokre av cellene allereie har ei vakt, tilbyr menyen begge måtane i klårt språk &mdash; <em>Lim inn i alle 7</em> og <em>Lim inn i 6 tomme celler</em> &mdash; så du vel før du gjennomfører i staden for etterpå. Å skrive over ber deg stadfeste og seier kor mange vakter det erstattar; å fylle tomromma berre skjer, sidan ingenting går tapt. Dei same menyane kan òg <strong>tømme</strong> ein dag, ei veke eller eit utval, igjen etter å ha fortalt deg kor mange vakter det fjernar.',
            'rota_step5' => '<strong>Kopier ein heil dag eller ei heil veke for éin person</strong> &mdash; høgreklikk ei <strong>dagoverskrift</strong> og vel <em>Kopier</em> for å hente kvar vakt den dagen, eller <strong>namnet til ein analytikar</strong> for å hente heile veka deira. Å lime inn på ein annan dag, eller ein annan analytikar, gjer at det stemmer: vakter kopien ikkje hadde, blir tømde, så du får dagen du kopierte i staden for ein blanding av dei to. Ein dag kan berre limast inn på ein annan dag, og ein analytikar berre på ein annan analytikar &mdash; ein dag er éi vakt <em>per person</em>, og ei veke er éi vakt <em>per dag</em>, så det er ingen fornuftig måte å leggje den eine over den andre på. Prøv det, og menyen seier frå, og seier kvar det kan gå i staden.',
            'rota_step6' => '<strong>Kopier ei heil veke</strong> &mdash; <strong>Kopier veke</strong> og <strong>Lim inn veke</strong> oppe til høgre hentar kvar vakt i veka du ser på, og slepp dei på ei anna, som er den raskaste måten å byggje ei gjentakande vaktliste på. Å lime inn <em>erstattar</em> målveka, så stadfestinga fortel deg kor mange oppføringar som er i ferd med å bli fjerna. Han rører berre dagane og personane rutenettet faktisk viser deg.',
            'tip' => 'Kombiner kalenderen og vaktlista for effektiv kapasitetsplanlegging. Viser kalenderen ein topp i saker kvar måndag morgon, sørgjer du for at vaktlista har ekstra dekning sett opp akkurat der.',
        ],
        'settings' => [
            'heading' => 'Innstillingar',
            'intro' => 'Innstillingar-sida er der du set opp byggjeklossane i saksbehandlingssystemet ditt. Alle oppslagsverdiar, SLA-mål, e-postintegrasjon og eigendefinerte felt blir handterte her.',
            'sla_callout_title' => 'SLA-handtering &mdash; heile rettleiinga',
            'sla_callout_body' => 'Valmoglegheiter, arbeidskalendrar, statusar som set klokka på pause, varsel ved brot, oppsett av cron-jobb, pluss gjennomgåtte døme for team i éi tidssone og på tvers av tidssoner. Omfattande nok til å fortene si eiga side.',
            'card_dept_title' => 'Avdelingar',
            'card_dept_body' => 'Opprett avdelingar som IT, HR og økonomi. Kvar avdeling blir ei mappe i innboksen og eit filter på oversikta',
            'card_types_title' => 'Sakstypar',
            'card_types_body' => 'Definer typane førespurnader servicedesken din handterer: hending, tenesteførespurnad, problem, endring. Typar hjelper analytikarar med å klassifisere arbeid',
            'card_type_rules_title' => 'Type for nye saker',
            'card_type_rules_body' => 'Under Sakstypar gir du kvar ny sak ein type når ingen vel ein: ein standard, og reglar framfor han - etter korleis ho kom inn (e-post, portal, nettprat, telefon, overvaking...), postkasse, opphav, avdeling, ord i emnet eller domenet til bestillaren. Den første regelen som passar vinn; Prøv det viser kva type ei sak ville fått',
            'card_priorities_title' => 'Prioritetar',
            'card_priorities_body' => 'Set prioritetsnivå med namn, fargar og sorteringsrekkjefølgje. Kvar prioritet blir knytt til eit SLA-mål for respons og løysing',
            'card_statuses_title' => 'Statusar',
            'card_statuses_body' => 'Tilpass stega i saksforløpet. Standardstatusane er mellom anna Ny, Open, Under arbeid, Ventar, Løyst og Lukka',
            'card_categories_title' => 'Kategoriar',
            'card_categories_body' => 'Grupper saker etter teknisk område: maskinvare, programvare, nettverk, tilgang. Kategoriar driv oppdelinga i rapportar',
            'card_sla_title' => 'SLA-mål',
            'card_sla_body' => 'Definer mål for responstid og løysingstid per prioritet. SLA-klokker blir viste på saker og utløyser åtvaringar om brot',
            'card_email_title' => 'E-postimport',
            'card_email_body' => 'Kople til ei postkasse (Exchange, Microsoft 365) for å importere e-postar som nye saker automatisk. Svar blir tråda tilbake inn i eksisterande saker',
            'card_custom_title' => 'Eigendefinerte felt',
            'card_custom_body' => 'Legg eigne felt på saker for data organisasjonen din må fange opp, og som standardfelta ikkje dekkjer',
            'card_templates_title' => 'E-postmalar',
            'card_templates_body' => 'Set opp varselmalane som blir sende til sluttbrukarar når saker blir oppretta, oppdaterte eller løyste, og for KTI-undersøkinga. Legg inn flettekodar som [requester_name] og [csat_link]',
            'card_checklists_title' => 'Sjekklister',
            'card_checklists_body' => 'Avgjer kva som skjer når nokon lukkar ei sak som framleis har obligatoriske sjekklistesteg som ikkje er fullførte: <strong>åtvar</strong> og registrer eit internt notat som namngjev stega og kven som lukka saka, eller <strong>blokker</strong> lukkinga til dei er fullførte. Gjeld overalt ei sak kan lukkast - massehandlingar, REST-API-et og arbeidsflytautomatisering inkludert',
            'card_custom_fields_title' => 'Eigendefinerte felt',
            'card_custom_fields_body' => 'Lag dei ekstra opplysningane ein type sak treng - tekst, eit tal, ein dato, ja / nei, ei nedtrekksliste med dine eigne val, ei nett- eller e-postadresse - og knyt kvar av dei til nokre sakstypar eller til alle. Kvart felt vel om det må fyllast ut <strong>når saka blir registrert</strong> (skjemaet Ny sak, REST API-et og, viss ønskt, portalen), <strong>før ho blir lukka</strong> (etter regelen for obligatoriske felt), eller begge, og om <strong>bestillaren blir spurd</strong> om det i portalen - der ei sakstypevelgjar dukkar opp når han endrar kva som blir spurt om. Svara blir viste i eigenskapspanelet til saka og i historikken hennar. Å endre sakstypen skjuler svara den nye typen ikkje har, og sletter dei aldri',
            'card_mandatory_title' => 'Obligatoriske felt',
            'card_mandatory_body' => 'Kryss av felta som må fyllast ut før ei sak kan lukkast - kategori, løysingskode, eigar og så vidare. Vel så kva som skjer når nokon lukkar ei med eit tomt felt: <strong>åtvar</strong>, <strong>åtvar og send e-post</strong> til nokon som ein leveranseansvarleg, eller <strong>nekt</strong> lukkinga. Ein eigen brytar registrerer det på saka som eit internt notat. Eit felt slått av for eit selskap er aldri påkravd, og samanslåing av saker utløyser det aldri. Handheva overalt ei sak kan lukkast - bulkhandlingar, REST-API-et og arbeidsflytautomatisering inkludert',
            'card_cleanup_title' => 'KI for opprydding i svar',
            'card_cleanup_body' => 'Anthropic-nøkkel + modell + tone for ✨ Rydd opp-knappen i svareditoren. Eigen nøkkel åtskild frå dei andre KI-funksjonane, for finmaska fakturering',
            'card_csat_title' => 'KTI',
            'card_csat_body' => 'Sendemåte (av / automatisk / manuelt), forseinking, vakt for éi per sak, skala (stjerner eller emojiar). Sjå del 6 for heile flyten',
            'email_heading' => '<strong>E-postimport i detalj</strong>',
            'email_body' => 'E-postimporten koplar seg til den delte postkassa di og hentar inn nye meldingar som saker. Når ein sluttbrukar sender ein e-post til supportadressa di (til dømes support@dittfirma.no), opprettar FreeITSM ei sak med emnet på e-posten som tittel og teksten som skildring. Svarar avsendaren på ein varsel-e-post, blir svaret tråda inn i den eksisterande saka i staden for å lage eit duplikat.',
            'email_step1' => '<strong>Set opp postkassa</strong> &mdash; gå til Innstillingar og fyll inn Exchange- eller Microsoft 365-opplysningane dine. OAuth-autentisering er støtta for sikre tilkoplingar utan passord.',
            'email_step2' => '<strong>Set hentefrekvens</strong> &mdash; vel kor ofte FreeITSM skal sjekke postkassa for nye meldingar. Kortare intervall tyder at saker blir oppretta raskare.',
            'email_step3' => '<strong>Set standardverdiar</strong> &mdash; vel standard avdeling, type og prioritet for saker som blir oppretta frå e-post. Analytikarar kan justere desse etter importen.',
            'email_thread_note' => '<strong>Eit svar utan saksnummer</strong> &mdash; kvar e-post FreeITSM sender har saksnummeret, så eit svar på han finn alltid saka si. Når nokon svarar på sin <em>eigen</em> første e-post i staden (for å leggje ved eit vedlegg dei gløymde, til dømes), finst det inga nummer å finne, og som standard startar det svaret ei ny sak. Sett Saker &rarr; Innstillingar &rarr; Generelt &rarr; <strong>Eit svar utan saksnummer</strong> til <strong>Blir med i saka samtalen høyrer til</strong>, så går det til saka den første e-posten opna i staden, og opnar henne på nytt viss ho var lukka (når gjenopning er på). Berre e-postar i same postkasse blir samanlikna.',
            'email_reply_to_note' => '<strong>Kven Svar svarar til</strong> &mdash; som standard er Svar-boksen adressert til personen på meldinga du les. Viss kollegaer til bestillaren blir med i tråden og du heller alltid vil svare bestillaren, set Saker &rarr; Innstillingar &rarr; Generelt &rarr; <strong>Svar går til</strong> til <strong>Bestillaren av saka</strong>. Du kan alltid endre adressa før du sender.',
            'email_sent_copy_note' => '<strong>Ein kopi av sendt post i Sendt-mappa (Basic IMAP)</strong> - ei Basic IMAP-postkasse sender gjennom SMTP, som ikkje tek vare på nokon kopi, så alle som les den same postkassa i Thunderbird eller nettpost ville ikkje sjå kva servicedesken sende. Rediger postkassa og slå på <strong>Lagre ein kopi av sendt post</strong>, rett under <em>Bruk IMAP-innlogginga for sending</em>: kvart svar, malt e-post, arbeidsflyt-e-post og system-e-post han sender blir då òg lagt i Sendt-mappa, merkt som lesen. Interne varsel til analytikarar blir aldri arkiverte. La <strong>Sendt-mappe</strong> stå tom for å bruke mappa e-postserveren din merkjer som Sendt, eller skriv namnet hennar. La bryteren vere av viss e-postserveren din alt arkiverer sendt post (Gmail og Microsoft 365 gjer det, og nokre vertsfirma) - du ville fått to kopiar. <strong>Test</strong> seier kva for ei mappe kopien gjekk til. Viss ein kopi ikkje kan lagrast, er e-posten likevel sendt, og grunnen blir lista i fana <strong>Aktivitet</strong> &rarr; <strong>Utgåande</strong> til postkassa som <em>Kopi til Sendt-mappe</em>.',
            'tip' => 'Bruk e-postmalar for å halde ein profesjonell og einsarta tone i all kommunikasjon med sluttbrukarar. Malar støttar dynamiske plasshaldarar for saksreferanse, namn på innmeldar, namn på analytikar og status.',
            'closemsg_heading' => '<strong>Ei eingongsmelding når du lukkar ei sak</strong>',
            'closemsg_body' => 'Set <code>[ticket_closed_message]</code> kvar som helst i ein aktiv <strong>Sak lukka</strong>-mal, og frå då av vil det å setje ei sak til ein lukka status be analytikaren om ei setning - <em>&ldquo;reservelagaren er på pulten din&rdquo;</em>, <em>&ldquo;lukkar som avtalt på telefonen&rdquo;</em>. Kva dei enn skriv, hamnar nøyaktig der du sette plasshaldaren, så du held kontroll på ordlyden rundt ho. Det er ikkje ei innstilling, og ingenting lagrar det: eitt notat, éi sak, éin e-post. Skriv ingenting, og linja er rett og slett ikkje der - ingen luke, ingen villleidande teiknsetjing.',
            'closemsg_note' => '<strong>Meldinga dukkar berre opp når plasshaldaren faktisk er i malen.</strong> Utan ho ville alt ein analytikar skreiv, blitt stille kasta vekk, og kvar skranke som ikkje vil ha dette, ville fått eit ekstra klikk på kvar einaste lukking. Så ho slår seg sjølv på når du set ho opp, og held seg unna når du ikkje har.',
            'cat_heading' => '<strong>Kategoriar, og dei to felta ved sida av dei</strong>',
            'cat_body' => '<em>Typen</em> til ei sak seier kva slags ting dette er; ein <em>kategori</em> seier kva det handlar om. Bygg lista under <strong>Innstillingar &rarr; Kategoriar</strong>, saman med brytarane som avgjer om noko av det i det heile dukkar opp på ei sak.',
            'cat_card_one_title' => 'Kategori',
            'cat_card_one_body' => 'Kva saka vart meldt inn som, valt når ho blir oppretta. Ei sak har nøyaktig éin, så ein rapport over kategoriane dine summerer alltid til talet på saker du faktisk hadde.',
            'cat_card_close_title' => 'Kategori ved lukking',
            'cat_card_close_body' => 'Den same lista spurt om att når saka blir avslutta. Vanlegvis stadfestar analytikaren berre &mdash; ho gjer nytte for seg på dei sakene der det første gjettet var feil, som er slik du finn ut at tolv av dei trettisju "skrivarproblema" dine eigentleg var nettverket.',
            'cat_card_res_title' => 'Løysingskode',
            'cat_card_res_body' => 'Korleis saka enda, heller enn kva ho handla om &mdash; "Fiksa eksternt", "Opplæring gjeve", "Ingen feil funne". Ti fornuftige er der frå starten, og du kan endre alle.',
            'cat_rule_off' => '<strong>Alle tre startar slått av.</strong> Bygg lista di først, slå så på dei du vil ha. Kvar kan setjast ulikt for kvart selskap.',
            'cat_rule_levels' => 'Kategoriar kan ha underkategoriar opptil tre nivå djupt, og ingen nivå er obligatorisk.',
            'cat_rule_type' => 'Ein kategori kan knytast til éin sakstype, så "Innrullering av brukar" blir berre tilbode på ein tenesteførespurnad. Knytinga høyrer til toppnivå-kategorien, og underkategoriane følgjer henne.',
            'cat_rule_typechange' => '<strong>Å endre typen på ei sak tømer ein kategori som høyrde til den gamle</strong>, og seier frå om det på skjermen. Ein kategori som ikkje er knytt til nokon type, overlever endringa.',
            'cat_rule_portal' => 'Kryss av <em>Kundar kan velje denne</em> for å tilby ein kategori i sjølvbetjeningsportalen. Bestillarar ser ei kort liste i klårt språk, medan analytikarar ser heile treet.',
            'cat_rule_retire' => 'Slå av ein kategori for å pensjonere han &mdash; han blir ståande på sakene som allereie har han, og sluttar å bli tilboden på nye. Det er nesten alltid betre enn å slette, som blir nekta så lenge noko framleis brukar han.',
            'cat_rule_report' => 'Alle tre kan visast i diagram på saksdashbordet. Dei to kategoridiagramma rullar opp til toppnivået, og saker utan noko sett blir talde som <em>Ikkje kategorisert</em> i staden for gøymde.',
            'cat_rule_workflow' => '<strong>Kategoriar i arbeidsflytar:</strong> ein arbeidsflyt kan rute saker etter kategori - eit <em>Kategori</em>-vilkår fungerer på kvar saksutløysar, og utløysaren <em>Kategorien til ei sak endrar seg</em> fangar ei sak som er kategorisert ved sortering. Som standard samsvarar eit vilkår som nemner ein kategori òg med underkategoriane, så «Maskinvare» fangar «Maskinvare &rarr; Bærbar»; vel <strong>Det samsvarar berre med den kategorien</strong> under <strong>Saker &rarr; Innstillingar &rarr; Kategoriar &rarr; Kategoriar i arbeidsflytar</strong> for å få kvar arbeidsflyt til å nemne kvar underkategori han vil ha. Når endring av typen til ei sak tømmer kategorien hennar, utløyser det òg utløysaren.',
            'cat_tip' => 'Viss du ikkje er sikker på kvar du skal starte, la kategoriane stå tomme og slå på <strong>Løysingskode</strong> åleine. Det er feltet som raskast endrar kva du gjer &mdash; ein femtedel av sakene dine som kjem tilbake som "Opplæring gjeve", er eit dokumentasjonsproblem, ikkje eit IT-problem.',
        ],
        'tips' => [
            'heading' => 'Raske tips',
            'search_title' => 'Søk i alt',
            'search_body' => 'Søkjevindauget ser på saksreferansar, emne, namn på innmeldarar og e-postadresser. Bruk det til å finne beslekta saker raskt når ein brukar ringjer om noko som alt er meldt.',
            'sla_title' => 'Følg med på SLA-ane',
            'sla_body' => 'SLA-klokker er synlege på kvar sak i lesefeltet. Fargekoda markørar blir gule når eit brot nærmar seg, og raude når målet er bomma på, så du kan prioritere deretter.',
            'reply_title' => 'Svar frå innboksen',
            'reply_body' => 'Du treng ikkje å opne e-postprogrammet ditt for å svare ein sluttbrukar. Bruk Svar-knappen i lesefeltet for å sende ei melding direkte. Ho blir tråda inn i saka automatisk.',
            'reply_to_title' => 'Kven Svar går til',
            'reply_to_body' => 'Svar er adressert til personen på meldinga du les. Viss du heller vil at det alltid skal gå til bestillaren av saka, endrar du <strong>Svar går til</strong> i Saker &rarr; Innstillingar &rarr; Generelt. Uansett kan du endre adressa, eller leggje til folk i Kopi, før du sender.',
            'trail_title' => 'Bruk aktivitetssporet',
            'trail_body' => 'Før du jobbar med ei sak, bør du bla gjennom aktivitetssporet. Tidlegare analytikarnotat, e-postar og feltendringar gjev deg heile samanhengen, så du slepp å be brukaren gjenta seg.',
            'dash_title' => 'Oversikt for leiarar',
            'dash_body' => 'Bygg ei oversikt med element for SLA-etterleving, gjennomsnittleg løysingstid og saker per avdeling. Del henne på teammøte for å drive kontinuerleg forbetring.',
            'rota_title' => 'Planlegg med vaktlista',
            'rota_body' => 'Fyll ut vaktlista minst to veker i førevegen. Kombinert med kalendervisinga hjelper ho deg å oppdage hol i dekninga før dei blir eit problem for responstidene.',
            'drag_title' => 'Dra for å triagere',
            'drag_body' => 'Dra saker frå lista inn i mapper for å oppdatere dei utan å opne dei. Undermapper for avdeling + status oppdaterer begge delar på éin gong. Fjørbelasta utviding gjer underliggjande statusar tilgjengelege medan du dreg.',
            'dbl_title' => 'Dobbeltklikk for fullskjerm',
            'dbl_body' => 'Eitt klikk førehandsviser ei sak i lesefeltet; dobbeltklikk opnar henne i fullskjerm for konsentrert arbeid. Klikk maksimer-ikonet ved emnet for å gå tilbake.',
            'rightclick_title' => 'Høgreklikk for raske handlingar',
            'rightclick_body' => 'Høgreklikk ei sak for å endre status, prioritet eller tildelt analytikar med eitt klikk, pluss kople CMDB-objekt og føre tid, alt utan å forlate saka du les akkurat no.',
            'ai_title' => 'Lat KI-en rydde opp i svaret ditt',
            'ai_body' => 'Skriv eit grovt utkast (eller berre punkt) og klikk <strong>✨ Rydd opp</strong> &mdash; Claude skriv det om til ein ordentleg e-post med helsing, retta grammatikk og avslutning. Ei angrelenkje blir vist i 30 sekund.',
            'feedback_title' => 'Be om tilbakemelding',
            'feedback_body' => 'Slå på KTI under <strong>Innstillingar &rarr; KTI</strong> for å spørje innmeldarar automatisk når sakene deira blir lukka. Trendar per analytikar ligg på <code>tickets/csat/</code> &mdash; gull verdt til utviklingssamtalar.',
            'precreate_title' => 'Opprett sluttbrukarar på førehand',
            'precreate_body' => '<strong>Brukarar</strong>-knappen i navigasjonen lèt deg leggje til ein brukar før dei treng å melde ei sak &mdash; lat passordet stå tomt, så kan dei ta over kontoen sjølve via sjølvbeteningsportalen.',
        ],
        'companies' => [
            'heading' => 'Firma &amp; e-postruting',
            'intro' => 'Når installasjonen din tener meir enn eitt firma (til dømes ein IT-leverandør som støttar fleire kundar), blir sakene til kvart firma haldne åtskilde. Denne delen forklarar korleis innkomande e-post finn rett firma.',
            'switcher_body' => 'Ein <strong>firmaveksel</strong> dukkar opp i toppfeltet. Han set firmaet du jobbar i &mdash; sakslista, mappene og teljingane viser berre det firmaet, og kvar sak du opprettar, hamnar der. Tilsette med tilgang til fleire firma kan byte mellom dei; det gjeldande blir alltid vist, så du kan ikkje svare i feil samanheng. Sjølve firmaa blir handterte under <strong>System &rarr; Firma</strong>.',
            'switcher_remember' => 'For å starte kvar innlogging i selskapet du sist valde (eller i <strong>Alle selskap</strong>) i staden for standardselskapet, slår du på <strong>Start i selskapet eg sist brukte</strong> under <strong>Innstillingar</strong> (kontomenyen din).',
            'mailboxes_heading' => 'Kvar postkasse er av eitt av to slag &mdash; det er dette som avgjer rutinga:',
            'card_pinned_title' => 'Knytt postkasse',
            'card_pinned_body' => 'Dedikert til eitt firma (til dømes ein kunde sin eigen <code>itsupport@</code>). <strong>All</strong> posten hennar hamnar hos det firmaet &mdash; avsendaren blir ignorert &mdash; og svar går ut frå henne, så kunden ser sin eigen servicedesk frå ende til annan.',
            'card_shared_title' => 'Postkasse for delt mottak',
            'card_shared_body' => 'Éi adresse som tener mange firma (til dømes ein leverandør sin eine <code>support@leverandoren.no</code>). Ho kan ikkje vite firmaet ut frå adressa åleine, så ho finn det ut frå <strong>kven som sende e-posten</strong>. Det tilrådde oppsettet for ein leverandør med mange kundar.',
            'routing_heading' => 'Slik vel ei postkasse for delt mottak firma',
            'routing_body' => 'For kvar innkomande e-post prøver ho desse i rekkjefølgje, og det første treffet vinn:',
            'flow_reply' => 'Svar på ei sak',
            'flow_sender' => 'Kjend avsendar',
            'flow_domain' => 'Kjent domene',
            'flow_triage' => 'Triage',
            'rule_reply' => '<strong>1. Svar på ei eksisterande sak</strong> &mdash; kjend att på referansen sin; e-posten blir ein del av den saka og tek vare på firmaet hennar.',
            'rule_sender' => '<strong>2. Ei bestemt avsendaradresse</strong> knytt til eit firma (til dømes <code>jane@gmail.com</code> &rarr; Acme) &mdash; det firmaet. Blir sjekka før domenet, så det verkar òg for private adresser og webmail.',
            'rule_domain' => '<strong>3. Domenet til avsendaren</strong> knytt til eit firma (til dømes alle <code>@acme.no</code> &rarr; Acme) &mdash; det firmaet.',
            'rule_triage' => '<strong>4. Ingen treff</strong> &mdash; e-posten går til <strong>triage</strong>-køen i staden for å gå tapt (sjå nedanfor).',
            'keys_heading' => 'Domene &amp; bestemte avsendarar (blir sette per firma under System &rarr; Firma)',
            'keys_body' => 'Dette er nøklane ei postkasse for delt mottak matchar på. Kvart firma listar e-postdomena det eig, og eventuelt einskildadresser.',
            'card_domains_title' => 'E-postdomene',
            'card_domains_body' => 'Domena eit firma eig (acme.no, acme.co.uk). Kvar avsendar på eit registrert domene blir ruta til det firmaet. Eit domene høyrer til berre eitt firma.',
            'card_senders_title' => 'Bestemte avsendarar',
            'card_senders_body' => 'Einskildadresser knytte til eit firma, sjekka før domenet. Bruk det for ein frilansar eller ein liten kunde som sender frå ei privat adresse.',
            'card_public_title' => 'Offentlege leverandørar',
            'card_public_body' => 'Gmail, Outlook, Yahoo og liknande kan ikkje knytast som eit domene (mange urelaterte personar deler dei) &mdash; knyt den nøyaktige adressa som ein bestemt avsendar i staden.',
            'triage_heading' => 'Triage-køen &mdash; tryggingsnettet',
            'triage_body' => 'Når ein e-post til delt mottak ikkje treffer noko firma, hamnar han i <strong>Triage</strong> (nådd frå firmavekselen, med ei løpande telling) i staden for å gå tapt. Kvart element viser avsendar, domene, emne og kva for ei postkasse han kom til. Legg han til eit firma i eitt steg:',
            'triage_create' => 'Vel eit eksisterande firma, eller opprett eit nytt på staden.',
            'triage_assign' => 'For eit vanleg domene kan du eventuelt <strong>rute det domenet</strong> til firmaet; for ei offentleg adresse eller webmail kan du eventuelt <strong>alltid leggje den avsendaren</strong> dit.',
            'triage_sweep' => 'Begge vala <em>feiar</em>: dei flyttar alle andre e-postar i køen frå det domenet eller den adressa òg, og rutar framtidig post automatisk &mdash; så du sorterer ein gjeven avsendar berre éin gong.',
            'triage_tip' => 'Ingenting går nokon gong tapt. Post utan treff ventar i triage til nokon legg han ein stad; ei sak som ikkje er lagd nokon stad, blir i mellomtida vist under standardfirmaet.',
            'test_heading' => 'Test rutinga di før du går i drift',
            'test_body' => 'Under <strong>System &rarr; Test av e-postruting</strong> kan du late som om ein e-post kom inn &mdash; vel ei postkasse, skriv ei avsendaradresse &mdash; og sjå nøyaktig kva for eit firma den nye saka ville hamna i (eller at ho ville gått til triage), og kva for ein regel som avgjorde det. Det blir ikkje oppretta noko; han berre les innstillingane dine.',
            'settings_heading' => 'Innstillingar: delte som standard, tilpassa der det betyr noko',
            'settings_body' => 'Nokre av desse innstillingane kan <strong>tilpassast per firma</strong>; andre held fram med å vere delte med vilje. Der ei innstilling er ei enkel liste med val &mdash; som <strong>sakstypar</strong> og <strong>kjelder</strong> &mdash; byter du inn i samanhengen til eit firma, og ser då dei delte standardane (kvar med eit augeikon for å skjule dei firmaet ikkje brukar) pluss det firmaet har lagt til berre for seg sjølv. Du kan ikkje skjule eller slette eit val medan opne saker framleis brukar det, og sjølve dei delte standardane blir redigerte frå MSP-en eller standardfirmaet.',
            'settings_custom_title' => 'Tilpassa per firma',
            'settings_custom_body' => 'Sakstypar &amp; kjelder (no), og kategoriar, SLA-ar &amp; arbeidstid (kjem) &mdash; ting som faktisk er ulike frå kunde til kunde.',
            'settings_global_title' => 'Delt på tvers av alle firma',
            'settings_global_body' => 'Statusar og prioritetar er like overalt, så rapportering på tvers av firma og SLA-ar held seg konsekvente; det same gjeld teama, vaktlista og postkassene dine &mdash; di eiga drift, ikkje ein kunde si.',
            'allview_heading' => '<strong>Éi tavle på tvers av alle selskap</strong>',
            'allview_body' => 'Selskapsbrytaren i toppteksten har eit <strong>Alle selskap</strong>-val. Kvar sak du har lov til å sjå, dukkar opp i éi liste, kvar rad merkt med selskapet ho høyrer til &mdash; nyttig når du støttar fleire einingar og vil ha eitt samla oversyn over dagen utan å miste oversikta over kva som er kva.',
            'allview_card_scope_title' => 'Det gjev ingen ny tilgang',
            'allview_card_scope_body' => '"Alle" tyder kvart selskap du allereie kunne nå éin om gongen. Ein analytikar som støttar to av dei tre einingane dine, ser nøyaktig dei to, og ein analytikar med eitt selskap ser eit oversyn over det eine selskapet.',
            'allview_card_props_title' => 'Kvar eining held seg åtskild',
            'allview_card_props_body' => 'Opne ei sak, og type-, opphavs-, kategori- og løysingslista er dei som høyrer til <em>det</em> selskapet &mdash; så ein kategori éi eining har og ei anna ikkje har, kan aldri brukast på feil sak.',
            'allview_card_new_title' => 'Nye saker spør kva selskap',
            'allview_card_new_body' => 'Det finst ikkje eitt einaste aktivt selskap å gå ut frå, og valet avgjer saksnummeret, postkassen svara kjem frå, og SLA-en som gjeld. Typelista fyller seg ut når du har valt.',
            'allview_rule_chip' => 'Ei sak som kom inn via e-post eller portalen utan å vere ruta enno, blir merkt <strong>Ikkje ruta</strong> i staden for vist under Standard, så ho skil seg ut for sortering.',
            'allview_rule_reply' => 'Svar går framleis ut frå postkassen saka kom inn på &mdash; det følgjer saka, ikkje visinga, så ei samla tavle kan aldri sende frå feil adresse.',
            'allview_rule_knowledge' => '<strong>Spør KI</strong> søkjer i kvart selskap du kan sjå medan den samla visinga er på, i staden for berre eitt. Artiklar delte med alle selskap er inkluderte uansett.',
            'allview_rule_trash' => '<strong>Å tømme papirkorga femner aldri fleire selskap.</strong> Ho gjeld alltid det eine selskapet du valde sist, fordi "slett alt i korga" på tvers av fleire einingar samstundes ikkje er det nokon meiner med det.',
            'allview_rule_other' => 'Berre sakslista blir breiare. Ressursar, endringar, oppgåver og CMDB-en viser framleis eitt selskap om gongen &mdash; byt til det selskapet for å jobbe i dei.',
            'privacy_heading' => 'Sakene til kvart firma blir haldne private',
            'privacy_body' => 'Når du jobbar i samanhengen til eit firma, ser du berre <strong>det</strong> firmaet sine saker &mdash; i lista, i søket, på oversikter og på kvar sak du opnar (medrekna e-postar, vedlegg, notat og historikk). Ein tilsett når berre ei sak dersom dei har fått tilgang til firmaet hennar (du vel firmaa til kvar analytikar under System &rarr; Analytikarar, eller gjev eit heilt team tilgang under System &rarr; Team), så det er ingen veg inn i ein annan kunde sine data. Denne separasjonen blir handheva overalt bak kulissane, ikkje berre skjult frå visinga. På ein installasjon med berre eitt firma skjer det automatisk og usynleg &mdash; det finst berre eitt firma, så alt høyrer rett og slett til det.',
            'tip' => 'På ein installasjon med berre eitt firma blir ingenting av dette vist &mdash; det finst eitt firma, kvar sak høyrer til det, og det er korkje veksel eller triage. Desse funksjonane slår seg på først når firma nummer to finst.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA-handtering',
        'back_link' => '&larr; Tilbake til saksrettleiinga',
        'sidebar_title' => 'SLA-rettleiing',
        'hero_title' => 'SLA-handtering',
        'hero_sub' => 'Mål for responstid og løysingstid som tek omsyn til arbeidstid, med varsel ved brot per avdeling',
        'nav' => [
            'overview' => 'Oversikt',
            'building_blocks' => 'Byggjeklossar',
            'behaviour_settings' => 'Innstillingar for åtferd',
            'breach_notifications' => 'Varsel ved brot',
            'cron_setup' => 'Oppsett av cron-jobb',
            'worked_examples' => 'Gjennomgåtte døme',
            'troubleshooting' => 'Feilsøking',
        ],
        'overview' => [
            'heading' => 'Oversikt',
            'sub' => 'Kva SLA-ar er, kvifor dei betyr noko, og korleis FreeITSM-motoren verkar på eit overordna nivå.',
            'p1' => 'Ein tenestenivåavtale (SLA) er ein lovnad om kor raskt teamet ditt skal svare på og løyse ei sak. FreeITSM følgjer to klokker per sak: <strong>respons</strong> (tida frå saka blir oppretta til første handling frå ein analytikar) og <strong>løysing</strong> (tida frå saka blir oppretta til ho blir lukka). Begge måla blir sette per prioritet &mdash; så ein P1 kan ha 30 minutt på respons og 4 timar på løysing, medan ein P4 kan ha 8 arbeidstimar og 5 arbeidsdagar.',
            'switch_note' => 'Brukar du ikkje SLA-ar? Slå av SLA under <strong>System &rarr; Modular &rarr; Tilgjenge &rarr; Saksfunksjonar</strong>: klokker, brotåtvaringar og SLA-utløysarar for arbeidsflyt stansar, medan arbeidskalendrane blir verande for opningstidene til nettpraten. Når du slår han på igjen, blir du spurd om åtvaringane som vart mista medan han var av skal sendast eller hoppast over.',
            'p2' => 'SLA-motoren i FreeITSM er bygd på fire designval det er verdt å forstå:',
            'choice_business' => '<strong>Arbeidstid, ikkje klokketid.</strong> Ein P2 som blir meld 16.30 med eit responsmål på éin time, bryt ikkje 17.30 dersom kontoret stengjer klokka 17. Klokka går vidare klokka 9 neste arbeidsdag. Dette er bransjestandarden og den einaste rettferdige modellen når analytikarar går heim om kvelden.',
            'choice_pause' => '<strong>Kan setjast på pause.</strong> Når ei sak har ein status merkt «Set SLA på pause» (til dømes <em>Ventar på svar</em> eller <em>På vent</em>), stoppar klokka. Ho går vidare når saka blir flytt tilbake til ein status det blir jobba i.',
            'choice_compute' => '<strong>Blir rekna ut ved lesing, ikkje lagra.</strong> Motoren reknar ut SLA-tilstanden frå revisjonsloggen til saka kvar gong du ser på han. Det finst ingen lagra teljarar som kan kome ut av takt. Endrar du timane i ein arbeidskalender seinare, blir SLA-en for kvar historisk sak rekna om mot dei nye timane neste gong ho blir vist.',
            'choice_cutoff' => '<strong>Grense for handheving.</strong> Ein administratorstyrt «Handhev SLA-ar frå»-dato tyder at eksisterande saker i systemet ditt ikkje plutseleg blir brot med tilbakeverkande kraft når du slår på SLA-ar. Berre saker som er oppretta på eller etter grensa, blir følgde.',
            'tip' => 'Er du ny i ITIL: responstid handlar om stadfesting (nokon har teke tak i saka); løysingstid handlar om fullføring (problemet til brukaren er løyst). Dei to klokkene går uavhengig av kvarandre og har ulike mål.',
        ],
        'blocks' => [
            'heading' => 'Dei fire byggjeklossane',
            'sub' => 'Set opp desse fire tinga, så verkar SLA-oppfølginga. Alt anna er finpuss du kan velje sjølv.',
            'cal_heading' => '1. Arbeidskalendrar',
            'cal_intro' => 'Ein kalender definerer når servicedesken din er open. Kvar kalender har:',
            'cal_tz' => '<strong>Tidssone</strong> &mdash; ei IANA-tidssone (til dømes <code>Europe/Oslo</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Overgangen til og frå sommartid blir handtert automatisk.',
            'cal_hours' => '<strong>Arbeidstid per veke</strong> &mdash; éi rad per vekedag med ein avkryssingsboks for ope og start- og sluttidspunkt. Nye kalendrar står som standard på mån–fre 09.00–17.00, stengt lau/søn. Ei rad som ikkje er merkt som open, tyder at servicedesken er stengd den dagen.',
            'cal_holidays' => '<strong>Heilagdagar</strong> &mdash; dato + valfritt namn. Heilagdagar overstyrer vekemønsteret (servicedesken er stengd sjølv om det fell på ein måndag).',
            'cal_default' => '<strong>Standardmerket</strong> &mdash; nøyaktig éin kalender er standard. Nye prioritetar arvar han med mindre du seier noko anna.',
            'cal_outro' => 'Du kan opprette så mange kalendrar du treng &mdash; éin per kontor, éin per team, éin for VIP-kundar med utvida opningstid. Dei blir delte av SLA-måla og motoren som sjekkar brot.',
            'prio_heading' => '2. Prioritetar med SLA-mål',
            'prio_intro' => 'Under Prioritetar-fana (eller via tabellen SLA-mål på SLA-fana) kan kvar prioritet ha:',
            'prio_response' => '<strong>Responsmål (minutt)</strong> &mdash; kor lenge det går til første handling frå ein analytikar.',
            'prio_resolution' => '<strong>Løysingsmål (minutt)</strong> &mdash; kor lenge det går til saka er lukka.',
            'prio_calendar' => '<strong>Kalender</strong> &mdash; kva for ein arbeidskalender klokka til denne prioriteten går mot. Lat feltet stå tomt for å bruke standardkalenderen.',
            'prio_outro' => 'Lèt du begge målfelta stå tomme, blir SLA-oppfølginga slått av heilt for den prioriteten &mdash; nyttig for ein prioritet som «Til informasjon» eller «Etterslep», der det ikkje er noko tidspress.',
            'pause_heading' => '3. Statusar som set SLA på pause',
            'pause_intro' => 'Under Statusar-fana finst ein eigen kolonne, «Set SLA på pause». Merk kvar status som tyder at saka er blokkert av noko utanfor kontrollen til teamet. Vanlege kandidatar er:',
            'pause_awaiting' => '<strong>Ventar på svar</strong> &mdash; kunden skuldar oss informasjon. Nesten universelt godteke som ein rimeleg pause.',
            'pause_vendor' => '<strong>På vent (leverandør)</strong> &mdash; ventar på Microsoft eller annan tredjepartsstøtte.',
            'pause_change' => '<strong>På vent (endringsvindauge)</strong> &mdash; planlagt til eit framtidig vedlikehaldsvindauge.',
            'pause_parts' => '<strong>På vent (delar)</strong> &mdash; ventar på levering av maskinvare.',
            'pause_warn' => 'Ein generell «På vent»-status kan misbrukast som ein nødutgang frå SLA-en når ei sak er vanskeleg eller analytikaren har mykje å gjere. Har teamet ditt disiplin, går det fint. Har det ikkje det, bør du vurdere å erstatte han med dei meir spesifikke variantane ovanfor, eller stole på <strong>Watchtower</strong>-oversikta, som markerer saker som har stått på pause i over 24 timar, med eit gult varsel.',
            'cutoff_heading' => '4. Grense for handheving (<code>Handhev SLA-ar frå</code>)',
            'cutoff_p1' => 'Den aller viktigaste globale innstillinga. Heilt til du set eit tidspunkt her, er SLA-oppfølginga slått av: ingen klokker går, ingen merke blir viste i innboksen, ingen e-postar om brot blir sende. Set du henne til eit tidspunkt tilbake i tid, blir SLA-ar slått på med tilbakeverkande kraft frå det punktet. Set du henne fram i tid, planlegg du når dei skal slåast på.',
            'cutoff_p2' => 'Dei fleste team set denne til «no» når dei slår på SLA-ar for første gong &mdash; eksisterande saker tek vare på tilstanden dei hadde før SLA-en, og nye saker frå det augeblinken blir følgde.',
            'company_heading' => 'Kvar kunde sine eigne prioritetar og timar',
            'company_p1' => 'På ei installasjon som tener fleire selskap kan ein prioritet eller ein arbeidskalender vere <strong>delt</strong> av alle selskap eller høyre til <strong>eitt selskap</strong> - vel i feltet <strong>Selskap</strong> når du legg han til. Eit selskap ser sine eigne prioritetar pluss dei delte det ikkje har skjult, og startar nye saker på sin eigen standard (elles den delte standarden). Kvar prioritetsvelgjar følgjer selskapet til saka, og kvar kanal som opnar ei sak startar henne på standarden til det selskapet.',
            'company_p2' => 'Klokka går på kalenderen til prioriteten sjølv; viss han ikkje har nokon, på standardkalenderen til selskapet; så den delte standarden. Ein delt prioritet kan berre bruke delte kalendrar. Å flytte ei sak til eit selskap som ikkje kan bruke prioriteten hennar byter ho til standarden til det selskapet, ført i historikken til saka.',
            'company_note' => 'Å endre ein <strong>delt</strong> prioritet eller kalender endrar han for alle selskap, så det krev tilgang til alle selskap. Eit selskap sin eigen krev tilgang til det selskapet. På ei installasjon med eitt selskap er alt dette usynleg - alt er delt.',
        ],
        'behaviour' => [
            'heading' => 'Innstillingar for åtferd',
            'sub' => 'Desse styrer korleis motoren reagerer i grensetilfelle. Standardverdiane er fornuftige &mdash; du treng berre å sjå på dei att dersom du har ein bestemt preferanse.',
            'prio_heading' => 'Når prioriteten blir endra undervegs',
            'prio_intro' => 'Dersom ei P3-sak blir oppgradert til P1 halvvegs (fordi problemet viser seg å vere større enn ein trudde), finst det tre rimelege åtferder:',
            'prio_forward' => '<strong>Framover (standard)</strong> &mdash; ta vare på dei opptente arbeidsminutta og berre byt mål. Hadde saka brukt 2 timar av P3-målet på 8 timar, har ho no brukt 2 timar mot P1-målet på 1 time &mdash; altså er ho alt i brot. Det kan forsvarast: saka VAR ein P1 heile tida, teamet skjøna det berre ikkje.',
            'prio_recompute' => '<strong>Rekn om</strong> &mdash; nullstill klokka og bruk det nye målet med tilbakeverkande kraft frå saka vart oppretta. Ei rein omrekning.',
            'prio_reset' => '<strong>Nullstill</strong> &mdash; start den nye klokka på nytt frå det augeblinken prioriteten vart endra. Mest tilgjevande overfor teamet, men kundar kan kjenne seg lurte dersom ei sak med høg prioritet plutseleg får ei fersk og lang klokke.',
            'reopen_heading' => 'Når ei lukka sak blir opna att',
            'reopen_intro' => 'Dersom ei sak blir opna att (brukaren svarar etter at ho er lukka):',
            'reopen_reset' => '<strong>Nullstill (standard)</strong> &mdash; start ei fersk klokke for både respons og løysing frå opninga att. Handsam opninga att som ei ny sak i praksis.',
            'reopen_continue' => '<strong>Hald fram</strong> &mdash; gå vidare frå tida som var gått ved lukking. Dei opphavlege SLA-måla held fram med å gjelde.',
            'first_heading' => 'Definisjonen av første respons',
            'first_intro' => 'Kva tel som «første respons» &mdash; augeblinken som stoppar responsklokka?',
            'first_either' => '<strong>Begge delar (standard)</strong> &mdash; den første handlinga frå ein analytikar av eit kva som helst slag: ein utgåande e-post, ei statusendring, ei tildeling.',
            'first_status' => '<strong>Statusendring</strong> &mdash; berre ei statusendring bort frå standardstatusen tel. Strengare &mdash; analytikaren må faktisk ha jobba med saka, ikkje berre klikka på henne.',
            'first_email' => '<strong>Utgåande e-post</strong> &mdash; berre eit e-postsvar til innmeldaren tel. Strengast &mdash; kunden må ha høyrt frå oss.',
            'warn_heading' => 'Prosent for åtvaringsterskel',
            'warn_body' => 'Kor langt ut i SLA-målet markøren skal gå frå grøn til gul. Standarden er 80 % &mdash; så eit responsmål på 60 minutt blir gult etter 48 minutt. Han driv òg varsla med utløysaren åtvaring.',
        ],
        'breach' => [
            'heading' => 'Varsel ved brot',
            'sub' => 'E-postreglar som kan setjast opp per avdeling, og som blir utløyste når SLA-ar nærmar seg brot (åtvaring) eller faktisk bryt.',
            'intro' => 'Kvar regel har fire dimensjonar, alle uavhengige av kvarandre:',
            'scope_heading' => '1. Omfang',
            'scope_body' => 'Anten <strong>Standard</strong> (regelen gjeld saker i alle avdelingar) eller ei <strong>bestemt avdeling</strong>. Oppløysing: ein avdelingsspesifikk regel vinn over standarden for saker i den avdelinga. Utan ein standardregel får avdelingar utan ein eigen regel ingen varsel.',
            'trigger_heading' => '2. Utløysar',
            'trigger_body' => 'Anten <strong>Åtvaring</strong> (saka har passert åtvaringsterskelen &mdash; mogleg brot) eller <strong>Brot</strong> (saka har overskride målet sitt &mdash; faktisk brot). Kvar av dei er sin eigen regel, så du kan varsle ulike personar for kvar.',
            'target_heading' => '3. Mål',
            'target_body' => 'Kva for ei klokke som skal følgjast &mdash; <strong>Respons</strong>, <strong>Løysing</strong> eller <strong>Begge</strong>.',
            'recip_heading' => '4. Mottakarar',
            'recip_intro' => 'Ein kva som helst kombinasjon av:',
            'recip_assignee' => '<strong>Den saka er tildelt</strong> &mdash; analytikaren som eig saka akkurat no. Blir hoppa over dersom ho ikkje er tildelt.',
            'recip_teams' => '<strong>Medlemer av teama til saksavdelinga</strong> &mdash; alle analytikarar i alle team som er knytte til avdelinga saka ligg i. Dekkjer heile køen utan at du må vedlikehalde ei distribusjonsliste.',
            'recip_specific' => '<strong>Ein bestemt analytikar</strong> &mdash; mønsteret med ein «SLA-ansvarleg» eller «tenesteleiar», der det er ein namngjeven person og ikkje ei rolle.',
            'recip_custom' => '<strong>Eigne e-postadresser</strong> &mdash; fritekst skild med komma. Nyttig for delte innboksar (<code>sla-varsel@firma.no</code>), e-postbruer til Slack/Teams, eller distribusjonslister.',
            'tip' => 'Kvar sak utløyser høgst éin e-post per (mål, utløysar) &mdash; cron-jobben held styr på kva som er sendt, i tabellen <code>sla_notifications_sent</code>. Så ei åtvaring blir utløyst éin gong, eit brot éin gong, og der stoppar det &mdash; ingen spamsløyfer.',
            'warn' => '<strong>Ingen reglar = ingen e-postar.</strong> Sjølv om kvar einaste sak i systemet bryt, skjer det ingenting før du legg til minst éin regel. Start med eit par på standardomfang, eitt for åtvaring og eitt for brot, så har du dekning for alt.',
        ],
        'cron' => [
            'heading' => 'Setje opp cron-jobben',
            'sub' => 'Skriptet som sjekkar brot, må køyre etter ein plan. Éin gong kvart femte minutt er det som fungerer best.',
            'p1' => 'SLA-markørane du ser i grensesnittet (merka i innboksen, panela i lesefeltet) blir rekna ut fortløpande når ei side blir lasta. Men e-postar om brot kan berre sendast dersom <em>noko</em> sjekkar sakene av seg sjølv, òg når ingen ser på dei. Det noko er ei planlagd oppgåve &mdash; på Windows Oppgåveplanlegging, på Linux cron.',
            'p2' => 'Skriptet er <code>cron/sla_breach_check.php</code> i installasjonsmappa til FreeITSM. Det kan startast på to måtar:',
            'cli_heading' => 'A. CLI (tilrådd på ein tenar du styrer sjølv)',
            'cli_note' => 'Inga autentisering er nødvendig &mdash; filrettane styrer alt kven som kan køyre det.',
            'http_heading' => 'B. HTTP (for delt nettdrift eller planleggjarar andre stader)',
            'http_note' => 'Tokenet blir laga automatisk ved første installasjon og lagra i <code>system_settings</code> under nøkkelen <code>sla_cron_token</code> (32 heksadesimale teikn, omtrent 128 bits entropi). Finn ditt med:',
            'win_heading' => 'Oppgåveplanlegging i Windows',
            'win_intro' => 'Opne Oppgåveplanlegging (<code>taskschd.msc</code>) og opprett ei ny oppgåve med desse innstillingane:',
            'tbl_field' => 'Felt',
            'tbl_value' => 'Verdi',
            'win_r1_k' => 'Namn',
            'win_r1_v' => 'FreeITSM &mdash; sjekk av SLA-brot',
            'win_r2_k' => 'Køyr anten brukaren er logga på eller ikkje',
            'win_r2_v' => 'Kryss av her',
            'win_r3_k' => 'Utløysar',
            'win_r3_v' => 'Dagleg, gjenta kvar dag, gjenta kvart 5. minutt i 1 dag',
            'win_r4_k' => 'Handling',
            'win_r4_v' => 'Start eit program',
            'win_r5_k' => 'Program/skript',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Legg til argument',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Start i',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron på Linux',
            'linux_intro' => 'Legg til éi linje i crontab-en din (<code>crontab -e</code>):',
            'sec_heading' => 'Tryggleik &mdash; kva som vernar HTTP-endepunktet',
            'sec_intro' => 'Tre lag, alle handheva automatisk:',
            'sec_token' => '<strong>1. Token som delt løyndom</strong> &mdash; 128 tilfeldige bits per installasjon, samanlikna med konstant tidsbruk for å hindre tidsåtak.',
            'sec_lockout' => '<strong>2. Utestenging per IP ved mislukka autentisering</strong> &mdash; meir enn 10 forsøk med feil token frå same IP den siste timen utløyser ei utestenging med 429 i éin time. Slår tilbake systematisk gjetting utan at du treng fail2ban.',
            'sec_interval' => '<strong>3. Minste intervall mellom vellukka køyringar</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (standard 30 s). Sjølv ein førespurnad med gyldig token får 429 dersom han kjem raskare enn dette etter førre vellukka køyring. Slår tilbake dobbeltplanlegging ved uhell og løpske sløyfer.',
            'log_heading' => 'Aktivitetslogg',
            'log_body' => 'Kvar køyring (godteken eller avvist) blir logga til tabellen <code>sla_cron_runs</code> med tidsbruk, resultat, tal og IP-en til klienten. Sjå dei siste 20 køyringane i <strong>Cron-aktivitet</strong>-panelet nedst på SLA-innstillingsfana &mdash; nyttig for å stadfeste at planen faktisk blir utløyst, og for å granske mislukka autentiseringsforsøk. Rader blir rydda automatisk etter <code>sla_cron_log_retention_days</code> (standard 30), så tabellen held seg liten.',
        ],
        'examples' => [
            'heading' => 'Gjennomgåtte døme',
            'sub' => 'Frå det enkle tilfellet med éi tidssone til det vanskelegare på tvers av tidssoner, der «rettferdig» må definerast.',
            'ex1_heading' => 'Døme 1: Sak meld i Storbritannia, servicedesk i Storbritannia',
            'ex1_title' => 'Det enkle tilfellet',
            'ex1_tag' => 'éi tidssone',
            'ex1_setup' => '<strong>Oppsett:</strong> Éin arbeidskalender kalla <em>Britisk kontor</em> med tidssona <code>Europe/London</code>, mån–fre 09.00–17.00, ingen heilagdagar. Prioriteten P2 har eit responsmål på 1 time og eit løysingsmål på 4 timar, begge mot kalenderen <em>Britisk kontor</em>.',
            'ex1_scenario' => '<strong>Scenario:</strong> Brukaren melder ei P2-sak <strong>16.30 britisk tid på onsdag</strong>.',
            'ex1_timeline' => 'Ons. 16.30 britisk tid &mdash; <strong>saka blir oppretta</strong>, responsklokka startar.
Ons. 17.00 britisk tid &mdash; kontoret stengjer, klokka blir sett på pause (30 min brukt av målet på 60 min).
Tors. 09.00 britisk tid &mdash; kontoret opnar, klokka går vidare.
Tors. 09.30 britisk tid &mdash; analytikaren svarar. Respons-SLA-en er akkurat nådd (60 min brukt, mål på 60 min).',
            'ex1_outro' => 'Hadde ikkje analytikaren svart før <strong>torsdag klokka 10.00 britisk tid</strong>, ville responsen vore <strong>i brot med 30 minutt</strong> (90 min brukt mot målet på 60 min &mdash; 30 frå onsdag kveld, 60 frå torsdag morgon). Klokka på 1 time går berre i arbeidstida, men ei sak som kjem ved slutten av dagen, et likevel opp mesteparten av budsjettet sitt over natta når kontoret opnar att &mdash; det er lett for ein analytikar som kjem klokka 09.00, å tru at dei har heile timen, når det i verkelegheita berre er 30 minutt att.',
            'ex2_heading' => 'Døme 2: Sak meld i Storbritannia, servicedesk i Estland',
            'ex2_title' => 'Tilfellet på tvers av tidssoner',
            'ex2_tag' => '3 måtar å definere «rettferdig» på',
            'ex2_setup' => '<strong>Oppsett:</strong> Britiske kundar (<code>Europe/London</code>, GMT/BST), estisk servicedesk (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 timar føre britisk tid</strong>). Begge deskane jobbar nominelt 09.00–17.00 lokal tid.',
            'ex2_scenario' => '<strong>Scenario:</strong> Ein britisk kunde melder ei P2-sak <strong>16.30 britisk tid på fredag</strong> (= 18.30 estisk tid, etter at Estland har stengt). Første høvet ein estisk analytikar har til å jobbe med henne, er måndag 09.00 estisk tid (= 07.00 britisk tid). Responsmålet er 1 time.',
            'ex2_question' => 'Kva bør SLA-en seie? Det finst tre svar som kan forsvarast, kvart rettferdig i si eiga forstand. Du vel kva for ein kalender prioriteten skal ha, ut frå kva tenesteavtalen din lovar.',
            'optA_label' => 'Alternativ A &mdash; med kunden i sentrum',
            'optA_p1' => '<strong>Set prioriteten til å bruke ein kalender med <em>britiske</em> timar.</strong> Klokka går mot britisk 09.00–17.00, uansett kvar analytikaren er.',
            'optA_p2' => 'I scenarioet over, sak meld 16.30 britisk tid fredag: klokka går 16.30&ndash;17.00 britisk tid fredag (30 min brukt), blir sett på pause over natta og helga, og går vidare måndag 09.00 britisk tid. Svarar ein estisk analytikar klokka 10.00 estisk tid måndag (= 08.00 britisk tid), er den britiske kalenderen framleis på pause (det britiske kontoret opnar 09.00 britisk tid), så det tikkar ingen ekstra minutt &mdash; forbruket står på 30 min. <strong>SLA nådd med 30 min margin</strong>. Eit svar etter 09.30 britisk tid (= 11.30 estisk tid) ville vore eit brot.',
            'optA_p3' => '<em>Rettferdig for:</em> kunden. Opplevinga deira følgjer deira eigen arbeidsdag.<br><em>Ulempa:</em> estiske analytikarar blir venta å vere tilgjengelege 09.00–17.00 britisk tid (= 11.00–19.00 estisk tid), noko som forlengjer arbeidsdagen deira med 2 timar.',
            'optB_label' => 'Alternativ B &mdash; med analytikaren i sentrum',
            'optB_p1' => '<strong>Set prioriteten til å bruke ein kalender med <em>estiske</em> timar.</strong> Klokka går mot estisk 09.00–17.00.',
            'optB_p2' => 'Same scenario: saka blir meld 18.30 estisk tid fredag (etter stengetid), klokka står på pause heile helga og byrjar å gå måndag 09.00 estisk tid (= 07.00 britisk tid). Svarar analytikaren 09.30 estisk tid måndag (= 07.30 britisk tid), har respons-SLA-en brukt 30 min av målet på 60 min &mdash; <strong>nådd med 30 min margin</strong>. Den britiske kunden melde saka 16.30 britisk tid fredag og fekk svar 07.30 britisk tid måndag &mdash; ventetida på klokka var mykje lengre enn SLA-en antydar.',
            'optB_p3' => '<em>Rettferdig for:</em> analytikarane. Dei jobbar normal arbeidstid.<br><em>Ulempa:</em> kundar i Storbritannia kan kjenne at SLA-en «lyg» dersom ei sak frå fredag ettermiddag ikkje blir stadfesta før måndag morgon estisk tid, medan rapporten seier at responstida var 1 time. Sørg for at tenesteavtalen din seier uttrykkeleg at SLA-en går mot opningstida til servicedesken.',
            'optC_label' => 'Alternativ C &mdash; overlappsvindauge (strengast)',
            'optC_p1' => '<strong>Set prioriteten til å bruke ein kalender som berre dekkjer timane der begge deskane er opne.</strong> Britisk 09.00–17.00 overlappar med estisk 09.00–17.00 (= britisk 07.00–15.00) i vindauget <strong>britisk 09.00–15.00</strong> &mdash; 6 timar per arbeidsdag.',
            'optC_p2' => 'Same scenario: saka blir meld 16.30 britisk tid fredag (utanfor overlappen, sidan overlappen stengjer 15.00 britisk tid), klokka står på pause over helga og går vidare måndag 09.00 britisk tid (= 11.00 estisk tid, augeblinken overlappen opnar att). Svarar den estiske analytikaren 11.30 estisk tid (= 09.30 britisk tid), har respons-SLA-en brukt 30 min av målet på 60 min &mdash; <strong>nådd med 30 min margin</strong>. Svaret kom i overlappsvindauget, så det tel med det same.',
            'optC_p3' => '<em>Rettferdig for:</em> begge sider &mdash; SLA-en går berre i timar der servicedesken faktisk kunne fått saka vidare OG kunden sit ved pulten sin og kan ta imot eit svar.<br><em>Ulempa:</em> eit kortare vindauge per dag tyder lengre klokketid for å nå ambisiøse mål. Eit løysingsmål på 4 timar strekkjer seg over 1,5 dagar med overlapp, der det med ein vanleg kalender på 8 timar ville vore gjort i løpet av éin dag.',
            'choose_tip' => '<strong>Slik vel du:</strong> sjå på tenesteavtalen din. Seier han «svar innan 1 time etter mottak» &mdash; då er det alternativ A (klokka til kunden). Seier han «svar innan 1 arbeidstime» &mdash; då er det typisk alternativ B (den desken som er på jobb). Seier han «innan 1 time med gjensidig tilgjenge» &mdash; då er det alternativ C. Finst det ingen avtale, spør teamet: vil de kjenne presset utanfor estisk arbeidstid (alternativ A), eller vil de at britiske kundar av og til skal kjenne seg oversedde (alternativ B)?',
            'ex3_heading' => 'Døme 3: Pause på klokka medan ein ventar på ein leverandør',
            'ex3_title' => 'Slik verkar pausestatusar i praksis',
            'ex3_tag' => 'pause på klokka',
            'ex3_setup' => '<strong>Oppsett:</strong> Prioriteten P3 med eit løysingsmål på 8 arbeidstimar, britisk kalender, og statusen «Ventar på leverandør» merkt <em>Set SLA på pause</em>.',
            'ex3_scenario' => '<strong>Scenario:</strong> Saka blir meld måndag 09.00 britisk tid. Analytikaren eskalerer til Microsoft måndag 11.00 britisk tid og flyttar saka til «Ventar på leverandør». Microsoft svarar onsdag 14.00 britisk tid. Analytikaren gjennomfører løysinga og lukkar saka torsdag 10.00 britisk tid.',
            'ex3_timeline' => 'Mån. 09.00 &mdash; saka blir oppretta, løysingsklokka går.
Mån. 11.00 &mdash; flytt til «Ventar på leverandør», <strong>klokka blir sett på pause</strong> (2t brukt).
Ons. 14.00 &mdash; flytt tilbake til «Under arbeid», <strong>klokka går vidare</strong>.
Ons. 17.00 &mdash; kontoret stengjer (5t brukt til saman).
Tors. 09.00 &mdash; kontoret opnar.
Tors. 10.00 &mdash; saka blir lukka (6t brukt til saman). <strong>SLA nådd</strong> mot målet på 8t.',
            'ex3_outro' => 'Tid på klokka: omtrent 3 dagar. Tid på SLA-en: 6 arbeidstimar. Utan merket for pausestatus ville SLA-en telt med alle dei 2 dagane med venting på leverandøren, i tillegg til arbeidstida, til saman omtrent 18 arbeidstimar &mdash; godt over brot.',
        ],
        'trouble' => [
            'heading' => 'Feilsøking',
            'sub' => 'Vanlege problem og kva du bør sjekke.',
            'col_symptom' => 'Symptom',
            'col_cause' => 'Sannsynleg årsak',
            'r1_s' => 'Det blir ikkje vist nokon SLA-merke i innboksen',
            'r1_c' => '<code>Handhev SLA-ar frå</code> er tom, prioriteten har ingen mål sette, eller saka er eldre enn grensa.',
            'r2_s' => 'SLA-en viser brot, men analytikaren svarte innanfor målet',
            'r2_c' => 'Sjekk historikken for prioritetsendringar &mdash; vart prioriteten oppgradert undervegs medan åtferda står på «Framover» (standard), blir den opptente tida teken med vidare.',
            'r3_s' => 'Varsel om brot blir ikkje sende',
            'r3_c' => '(1) Ingen reglar er sette opp. (2) Cron-jobben er ikkje planlagd. (3) Reglar er sette opp, men mottakarane kan ikkje bestemmast (ingen tildelt analytikar, teama til avdelinga har ingen medlemer med e-post). Sjekk Cron-aktivitet-panelet for oppsummeringa per køyring.',
            'r4_s' => 'Cron køyrer, men melder «ingen regel passar»',
            'r4_c' => 'Legg til minst éin regel med standardomfang, slik at alle avdelingar er dekte.',
            'r5_s' => 'Watchtower viser «N saker på pause i over 24 t»',
            'r5_c' => 'Saker står i ein status som set SLA-en på pause. Anten har nokon parkert dei med vilje og gløymt dei, eller så brukar nokon På vent som ein nødutgang frå SLA-en. Klikk deg inn på kvar av dei og anten få dei vidare eller ta bort pausestatusen.',
            'r6_s' => 'HTTP-cron svarar 403',
            'r6_c' => 'Tokenet i URL-en stemmer ikkje. Slå det opp med <code>SELECT setting_value FROM system_settings WHERE setting_key = \'sla_cron_token\'</code>.',
            'r7_s' => 'HTTP-cron svarar 429 «Rate limited»',
            'r7_c' => 'Ei vellukka køyring vart fullført for mindre enn <code>sla_cron_min_interval_seconds</code> sidan (standard 30 s). Vent, eller senk innstillinga.',
            'r8_s' => 'HTTP-cron svarar 429 «Too many failed attempts»',
            'r8_c' => 'Denne IP-en har passert 10 forsøk med feil token den siste timen. Vent 1 time, eller tøm feila: <code>DELETE FROM sla_cron_runs WHERE client_ip = \'...\' AND outcome = \'auth_failed\'</code>.',
            'tip' => 'For ein grundig teknisk gjennomgang av cron-oppsettet, medrekna Linux-døme og integrasjon med planleggjarar andre stader, sjå <code>docs/sla-cron-setup.md</code> i installasjonsmappa til FreeITSM.',
